import React, { useState, useContext, useRef, FormEvent, ChangeEvent } from 'react';
import { DataContext } from '../context/DataContext';
import { Anuncio, Aula } from '../types';
import { XIcon, UploadCloudIcon, FileTextIcon, PlusCircleIcon, TrashIcon, LogOutIcon, CameraIcon } from './Icons';

// Helper function to calculate shift based on time
const calcularTurno = (inicio: string): string => {
    if (!inicio) return '';

    const [horas, minutos] = inicio.split(':').map(Number);
    const totalMinutos = horas * 60 + minutos;

    // Manhã: 06:00 (360) a 11:30 (690)
    // Tarde: 11:50 (710) a 17:50 (1070)
    // Noite: 17:51 (1071) a 22:00 (1320)

    if (totalMinutos >= 360 && totalMinutos <= 690) return 'Manhã';
    if (totalMinutos >= 710 && totalMinutos <= 1070) return 'Tarde';
    if (totalMinutos >= 1071) return 'Noite'; // Cobre até o final do dia basicamente

    // Fallbacks para intervalos não cobertos (ex: 11:40), atribui ao mais próximo anterior ou posterior
    if (totalMinutos < 360) return 'Manhã'; // Antes das 6h
    if (totalMinutos > 690 && totalMinutos < 710) return 'Manhã'; 
    if (totalMinutos > 1070 && totalMinutos < 1071) return 'Tarde';

    return 'Noite';
};

// Toast Notification Component
const Toast: React.FC<{ message: string; type: 'success' | 'error'; onClose: () => void }> = ({ message, type, onClose }) => {
  const bgColor = type === 'success' ? 'bg-green-500/80' : 'bg-red-500/80';
  const borderColor = type === 'success' ? 'border-green-400' : 'border-red-400';

  React.useEffect(() => {
    const timer = setTimeout(onClose, 5000); // Increased duration for readability
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`fixed top-5 right-5 ${bgColor} ${borderColor} border text-white p-4 rounded-lg shadow-lg z-50 backdrop-blur-sm flex items-center gap-4 max-w-sm`}>
      <span>{message}</span>
      <button onClick={onClose} aria-label="Fechar notificação">
        <XIcon className="w-5 h-5" />
      </button>
    </div>
  );
};


// Login Modal Component
