const DashboardScreen: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const context = useContext(DataContext);
    const [displayAulas, setDisplayAulas] = useState<Aula[]>([]);
    const [currentShift, setCurrentShift] = useState<string>('Manhã');

    // Effect to determine current shift based on time
    useEffect(() => {
        const updateShift = () => {
            const now = new Date();
            const totalMinutes = now.getHours() * 60 + now.getMinutes();

            // Intervalos definidos:
            // Manhã: até 11:30 (mas vamos estender a visualização até 11:50 para cobrir o intervalo)
            // Tarde: 11:50 a 17:50
            // Noite: 17:51 a 22:00

            // Lógica de visualização:
            // < 11:50 (710 min) -> Mostra Manhã
            // 11:50 a 17:50 (1070 min) -> Mostra Tarde
            // > 17:50 -> Mostra Noite

            if (totalMinutes < 710) { 
                setCurrentShift('Manhã');
            } else if (totalMinutes <= 1070) {
                setCurrentShift('Tarde');
            } else {
                setCurrentShift('Noite');
            }
        };

        updateShift(); // Run immediately
        const interval = setInterval(updateShift, 60000); // Check every minute
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (context && !context.loading) {
            // Filter classes based on the calculated shift
            // If a class doesn't have a shift defined (old data), we show it regardless to prevent data loss visibility, 
            // OR strict mode: only match. Let's do strict match to satisfy request.
            const filtered = context.aulas.filter(aula => {
                // Normaliza strings para evitar erros de case (manhã vs Manhã)
                const aulaTurno = aula.turno?.toLowerCase();
                const currShift = currentShift.toLowerCase();
                return aulaTurno === currShift;
            });
            setDisplayAulas(filtered);
        }
    }, [context, currentShift]);

    if (!context) {
        return <div className="text-red-500">Erro: Contexto não encontrado.</div>;
    }

    const { loading, error, anuncio } = context;

    return (
        <div className="min-h-screen bg-gradient-to-br from-[#0b0b0f] to-[#1a1a20] text-white p-4 pt-24">
            <Header currentShift={currentShift} />
            <main className="container mx-auto flex flex-col lg:flex-row gap-8">
                <div className="flex-1">
                    {error && <div className="bg-red-500/30 border border-red-500 text-red-300 p-4 rounded-lg text-center mb-6">{error}</div>}

                    {loading ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6">
                            {Array.from({ length: 8 }).map((_, i) => <SkeletonCard key={i} />)}
                        </div>
                    ) : displayAulas.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6">
                            {displayAulas.map((aula) => <ClassCard key={aula.id} aula={aula} />)}
                        </div>
                    ) : (
                        <div className="text-center py-20 bg-white/5 backdrop-blur-md rounded-2xl border border-white/10 flex flex-col items-center justify-center">
                            <div className="bg-white/10 p-4 rounded-full mb-4">
                                <ClockIcon className="w-12 h-12 text-white/50" />
                            </div>
                            <h2 className="text-2xl font-bold text-white/80">Sem aulas neste turno.</h2>
                            <p className="text-white/60 mt-2">Não há aulas cadastradas para o período da <span className="text-[#ff6600] font-bold">{currentShift}</span>.</p>
                        </div>
                    )}
                </div>
                {anuncio && anuncio.src && (
                     <aside className="w-full lg:max-w-sm xl:max-w-md hidden lg:block">
                        <AnnouncementPanel anuncio={anuncio} />
                    </aside>
                )}
                {/* Mobile Announcement fallback if needed, currently hidden implies design choice */}
            </main>
            <button
                onClick={onAdminClick}
                aria-label="Acessar painel de administração"
                className="fixed bottom-6 right-6 bg-[#ff6600] text-white p-4 rounded-full shadow-lg hover:bg-[#ff8533] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[#1a1a20] focus:ring-[#ff6600] transition-all duration-200 transform hover:scale-110 z-50 opacity-50 hover:opacity-100"
            >
                <SettingsIcon className="w-6 h-6" />
            </button>
        </div>
    );
};

