// Admin Panel Component
const AdminPanel: React.FC<{ onLogout: () => void }> = ({ onLogout }) => {
    const context = useContext(DataContext);
    const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);
    const [newAula, setNewAula] = useState<Omit<Aula, 'id'>>({ sala: '', turma: '', instrutor: '', unidade_curricular: '', inicio: '', fim: '' });
    const [mediaPreview, setMediaPreview] = useState<string | null>(null);
    const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
    const [importedPreview, setImportedPreview] = useState<Omit<Aula, 'id'>[]>([]);

    const fileInputRef = useRef<HTMLInputElement>(null);

    if (!context) return <p>Erro de contexto.</p>;

    const handleCSVUpload = (e: ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const text = event.target?.result as string;
            try {
                const parseCsvRow = (row: string): string[] => {
                    const result: string[] = [];
                    let current = '';
                    let inQuotes = false;
                    for (let i = 0; i < row.length; i++) {
                        const char = row[i];
                        if (char === '"') {
                            if (inQuotes && row[i + 1] === '"') { 
                                current += '"';
                                i++;
                            } else {
                                inQuotes = !inQuotes;
                            }
                        } else if (char === ',' && !inQuotes) {
                            result.push(current.trim().replace(/^"|"$/g, ''));
                            current = '';
                        } else {
                            current += char;
                        }
                    }
                    result.push(current.trim().replace(/^"|"$/g, ''));
                    return result;
                };

                const rows = text.split('\n').filter(row => row.trim() !== '');
                if (rows.length < 2) {
                    throw new Error('Arquivo CSV está vazio ou contém apenas o cabeçalho.');
                }

                const headerRow = rows.shift()!.trim();
                const headers = parseCsvRow(headerRow);

                // Mapeamento esperado
                const headerMapping: { [key: string]: string } = {
                    sala: 'Ambiente Educacional / Justificativa',
                    turma: 'Turma / Tipo Reserva',
                    instrutor: 'Instrutor/Ambiente Reserva',
                    unidade_curricular: 'Unidade Curricular / Solicitante',
                    inicio: 'Inicio',
                    fim: 'Fim',
                    turno: 'Turno' // Opcional, tentaremos encontrar
                };

                const colIndices: { [key: string]: number } = {};

                // Encontra índices das colunas obrigatórias
                const mandatoryFields = ['sala', 'turma', 'instrutor', 'unidade_curricular', 'inicio', 'fim'];
                for (const key of mandatoryFields) {
                    const csvHeader = headerMapping[key];
                    const index = headers.findIndex(h => h.trim() === csvHeader);
                    if (index === -1) {
                        throw new Error(`Coluna obrigatória não encontrada: "${csvHeader}".`);
                    }
                    colIndices[key] = index;
                }

                // Tenta encontrar coluna de turno (opcional)
                const turnoHeaderIndex = headers.findIndex(h => h.trim() === 'Turno' || h.trim() === 'Turno / Periodo');
                if (turnoHeaderIndex !== -1) {
                    colIndices['turno'] = turnoHeaderIndex;
                }

                const data: Omit<Aula, 'id'>[] = rows
                    .map((row, rowIndex) => {
                        if (!row.trim()) return null;

                        const values = parseCsvRow(row.trim());

                        // Verifica se tem colunas suficientes para os campos obrigatórios
                        const maxIndex = Math.max(...Object.values(colIndices).filter(v => v !== undefined));
                        if (values.length <= maxIndex && maxIndex > -1) {
                            console.warn(`Linha ${rowIndex + 2} ignorada: número de colunas insuficiente.`);
                            return null;
                        }

                        const cleanUnidadeCurricular = (uc: string = '') => {
                            return uc.replace(/\s*\(CH:.*\)/i, '').trim();
                        };

                        const inicio = values[colIndices.inicio] || '';

                        // Lógica de Turno: Tenta pegar do CSV, senão calcula
                        let turnoFinal = '';
                        if (colIndices['turno'] !== undefined && values[colIndices['turno']]) {
                            const turnoCsv = normalizarTurnoCSV(values[colIndices['turno']]);
                            if (turnoCsv) {
                                turnoFinal = turnoCsv;
                            } else {
                                turnoFinal = calcularTurno(inicio);
                            }
                        } else {
                            turnoFinal = calcularTurno(inicio);
                        }

                        const aulaData: Omit<Aula, 'id'> = {
                            sala: values[colIndices.sala] || '',
                            turma: values[colIndices.turma] || '',
                            instrutor: values[colIndices.instrutor] || '',
                            unidade_curricular: cleanUnidadeCurricular(values[colIndices.unidade_curricular]),
                            inicio: inicio,
                            fim: values[colIndices.fim] || '',
                            turno: turnoFinal
                        };

                        if (!aulaData.sala || !aulaData.turma || !aulaData.instrutor || !aulaData.inicio || !aulaData.fim) {
                             return null;
                        }

                        return aulaData;
                    })
                    .filter((item): item is Omit<Aula, 'id'> => item !== null);

                if (data.length === 0) {
                    throw new Error('Nenhuma linha válida encontrada.');
                }

                context.updateAulasFromCSV(data);
                setImportedPreview(data.slice(0, 5)); // Mostra os 5 primeiros
                setToast({ message: `${data.length} aulas importadas com sucesso!`, type: 'success' });

            } catch (err) {
                 const errorMessage = err instanceof Error ? err.message : 'Erro ao processar CSV.';
                 setToast({ message: errorMessage, type: 'error' });
            }
        };
        reader.readAsText(file, 'UTF-8');
    };

    const handleMediaUpload = (e: ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onloadend = () => {
            const result = reader.result as string;
            const type = file.type.startsWith('image') ? 'image' : 'video';
            setMediaPreview(result);
            setMediaType(type);
        };
        reader.readAsDataURL(file);
    };

    const handleUpdateAnuncio = () => {
        if (mediaPreview && mediaType) {
            context.setAnuncio({ src: mediaPreview, type: mediaType });
            setToast({ message: 'Mídia de anúncio atualizada!', type: 'success' });
        } else {
             setToast({ message: 'Nenhuma mídia selecionada.', type: 'error' });
        }
    };

    const handleAddAula = (e: FormEvent) => {
        e.preventDefault();
        if (Object.values(newAula).some(val => typeof val === 'string' && val.trim() === '')) {
            setToast({ message: 'Preencha todos os campos da aula.', type: 'error' });
            return;
        }

        const aulaComTurno = {
            ...newAula,
            turno: calcularTurno(newAula.inicio)
        };

        context.addAula(aulaComTurno);
        setNewAula({ sala: '', turma: '', instrutor: '', unidade_curricular: '', inicio: '', fim: '' });
        setToast({ message: 'Aula adicionada com sucesso!', type: 'success' });
    };

    const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
        setNewAula({ ...newAula, [e.target.name]: e.target.value });
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-[#0b0b0f] to-[#1a1a20] text-white p-4 sm:p-6 lg:p-8">
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
            <header className="flex justify-between items-center mb-8">
                <h1 className="text-3xl font-bold text-white">Painel Administrativo</h1>
                <button onClick={onLogout} className="flex items-center gap-2 text-white/80 hover:text-[#ff6600] transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-[#ff6600] rounded-lg p-2">
                    <LogOutIcon className="w-5 h-5"/> Sair
                </button>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Coluna de Uploads */}
                <div className="space-y-8">
                    {/* CSV Upload */}
                    <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                        <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><FileTextIcon /> Upload de Aulas (CSV)</h2>
                        <input type="file" accept=".csv" onChange={handleCSVUpload} className="hidden" ref={fileInputRef}/>
                        <button onClick={() => fileInputRef.current?.click()} className="w-full bg-black/20 border-2 border-dashed border-white/30 rounded-lg p-6 text-center text-white/70 hover:border-[#ff6600] hover:text-white transition-colors duration-200">
                            <UploadCloudIcon className="w-10 h-10 mx-auto mb-2"/>
                            Clique para enviar arquivo .csv
                        </button>
                        <p className="text-xs text-white/50 mt-2 text-center">Colunas esperadas: Inicio, Fim, Turma..., e opcionalmente <strong>Turno</strong> (Matutino/Vespertino/Noturno).</p>

                        {/* Preview Section */}
                        {importedPreview.length > 0 && (
                            <div className="mt-6 border-t border-white/10 pt-4">
                                <h3 className="text-sm font-bold text-white/80 mb-2">Últimas importadas (Pré-visualização):</h3>
                                <div className="overflow-x-auto">
                                    <table className="w-full text-xs text-left text-white/70">
                                        <thead className="text-white/50 bg-white/5 uppercase">
                                            <tr>
                                                <th className="px-2 py-1">Sala</th>
                                                <th className="px-2 py-1">Turma</th>
                                                <th className="px-2 py-1">Início</th>
                                                <th className="px-2 py-1 text-[#ff6600]">Turno</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {importedPreview.map((aula, i) => (
                                                <tr key={i} className="border-b border-white/5">
                                                    <td className="px-2 py-1 truncate max-w-[100px]">{aula.sala}</td>
                                                    <td className="px-2 py-1 truncate max-w-[100px]">{aula.turma}</td>
                                                    <td className="px-2 py-1">{aula.inicio}</td>
                                                    <td className="px-2 py-1 font-bold">{aula.turno}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Media Upload */}
                    <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                        <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><CameraIcon /> Mídia para o Painel</h2>
                        <input type="file" accept="image/*,video/*" onChange={handleMediaUpload} className="w-full text-sm text-white/70 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#ff6600] file:text-white hover:file:bg-[#ff8533]"/>
                        {mediaPreview && (
                            <div className="mt-4 border border-white/20 rounded-lg overflow-hidden">
                                {mediaType === 'image' ? <img src={mediaPreview} alt="Preview" /> : <video src={mediaPreview} controls className="w-full" />}
                            </div>
                        )}
                        <button onClick={handleUpdateAnuncio} className="mt-4 w-full bg-[#ff6600] text-white font-bold py-2 rounded-lg hover:bg-[#ff8533] transition-colors duration-200">Atualizar Anúncio</button>
                    </div>
                </div>

                {/* Coluna de Ações Manuais */}
                <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                    <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><PlusCircleIcon /> Cadastro Manual de Aula</h2>
                    <form onSubmit={handleAddAula} className="space-y-3">
                        <input name="sala" value={newAula.sala} onChange={handleInputChange} placeholder="Ambiente (Ex: Lab 01)" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <input name="turma" value={newAula.turma} onChange={handleInputChange} placeholder="Turma" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <input name="instrutor" value={newAula.instrutor} onChange={handleInputChange} placeholder="Instrutor" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <input name="unidade_curricular" value={newAula.unidade_curricular} onChange={handleInputChange} placeholder="Unidade Curricular" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <div className="flex gap-3">
                            <div className="w-1/2">
                                <label className="text-xs text-white/50 ml-1">Início</label>
                                <input name="inicio" value={newAula.inicio} onChange={handleInputChange} type="time" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                            </div>
                            <div className="w-1/2">
                                <label className="text-xs text-white/50 ml-1">Fim</label>
                                <input name="fim" value={newAula.fim} onChange={handleInputChange} type="time" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                            </div>
                        </div>
                        <button type="submit" className="w-full bg-green-600 text-white font-bold py-2 rounded-lg hover:bg-green-700 transition-colors duration-200">Adicionar Aula</button>
                    </form>

                    <div className="mt-8 pt-6 border-t border-white/20">
                         <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><TrashIcon /> Ações Gerais</h2>
                        <button onClick={context.clearAulas} className="w-full bg-red-600 text-white font-bold py-2 rounded-lg hover:bg-red-700 transition-colors duration-200">Limpar Todas as Aulas</button>
                    </div>
                </div>
            </div>
        </div>
    );
};


const AdminScreen: React.FC<{ onReturnToDashboard: () => void }> = ({ onReturnToDashboard }) => {
    const [isLoggedIn, setIsLoggedIn] = useState(false);
    const [loginError, setLoginError] = useState<string | null>(null);

    const handleLoginSuccess = () => {
        setIsLoggedIn(true);
        setLoginError(null);
    };

    const handleLoginError = (msg: string) => {
        setLoginError(msg);
        setTimeout(() => setLoginError(null), 3000);
    }

    const handleLogout = () => {
        setIsLoggedIn(false);
        onReturnToDashboard();
    };

    if (!isLoggedIn) {
        return (
          <>
            <LoginModal onLoginSuccess={handleLoginSuccess} onLoginError={handleLoginError} />
            {loginError && <Toast message={loginError} type="error" onClose={() => setLoginError(null)} />}
          </>
        )
    }

    return <AdminPanel onLogout={handleLogout} />;
};

