                        <input name="unidade_curricular" value={newAula.unidade_curricular} onChange={handleInputChange} placeholder="Unidade Curricular" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <div className="flex gap-3">
