const DashboardScreen: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const context = useContext(DataContext);
    const [displayAulas, setDisplayAulas] = useState<Aula[]>([]);
    const [currentShift, setCurrentShift] = useState<string>('Manhã');

    // Effect to determine current shift based on time
    useEffect(() => {
        const updateShift = () => {
            const now = new Date();
            const totalMinutes = now.getHours() * 60 + now.getMinutes();

            // Sincronizado com a lógica do AdminScreen:
            // < 12:00 (720 min) -> Manhã
            // >= 12:00 e < 18:00 (1080 min) -> Tarde
            // >= 18:00 -> Noite

            if (totalMinutes < 720) { 
                setCurrentShift('Manhã');
            } else if (totalMinutes < 1080) {
                setCurrentShift('Tarde');
            } else {
                setCurrentShift('Noite');
            }
        };

        updateShift(); // Run immediately
        const interval = setInterval(updateShift, 60000); // Check every minute
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (context && !context.loading) {
            const filtered = context.aulas.filter(aula => {
                const aulaTurno = aula.turno?.toLowerCase();
                const currShift = currentShift.toLowerCase();
                return aulaTurno === currShift;
            });
            setDisplayAulas(filtered);
        }
    }, [context, currentShift]);

    if (!context) {
        return <div className="text-red-500">Erro: Contexto não encontrado.</div>;
    }

    const { loading, error, anuncio } = context;

    return (
        <div className="min-h-screen bg-gradient-to-br from-[#0b0b0f] to-[#1a1a20] text-white p-4 pt-24">
            <Header currentShift={currentShift} />
            <main className="container mx-auto flex flex-col lg:flex-row gap-6 h-full min-h-[80vh]">
                {/* Lista de Aulas: Ocupa o espaço restante (flex-1) */}
                <div className="flex-1">
                    {error && <div className="bg-red-500/30 border border-red-500 text-red-300 p-4 rounded-lg text-center mb-6">{error}</div>}

                    {loading ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-6">
                            {Array.from({ length: 8 }).map((_, i) => <SkeletonCard key={i} />)}
                        </div>
                    ) : displayAulas.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-6">
                            {displayAulas.map((aula) => <ClassCard key={aula.id} aula={aula} />)}
                        </div>
                    ) : (
                        <div className="text-center py-20 bg-white/5 backdrop-blur-md rounded-2xl border border-white/10 flex flex-col items-center justify-center">
                            <div className="bg-white/10 p-4 rounded-full mb-4">
                                <ClockIcon className="w-12 h-12 text-white/50" />
                            </div>
                            <h2 className="text-2xl font-bold text-white/80">Sem aulas neste turno.</h2>
                            <p className="text-white/60 mt-2">Não há aulas cadastradas para o período da <span className="text-[#ff6600] font-bold">{currentShift}</span>.</p>
                        </div>
                    )}
                </div>

                {/* Painel de Anúncio: Largura fixa percentual em telas grandes (35% ou 40%) */}
                {anuncio && anuncio.src && (
                     <aside className="w-full lg:w-[35%] hidden lg:block">
                        <AnnouncementPanel anuncio={anuncio} />
                    </aside>
                )}
            </main>
            <button
                onClick={onAdminClick}
                aria-label="Acessar painel de administração"
                className="fixed bottom-6 right-6 bg-[#ff6600] text-white p-4 rounded-full shadow-lg hover:bg-[#ff8533] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[#1a1a20] focus:ring-[#ff6600] transition-all duration-200 transform hover:scale-110 z-50 opacity-50 hover:opacity-100"
            >
                <SettingsIcon className="w-6 h-6" />
            </button>
        </div>
    );
};

export default DashboardScreen;

import React, { createContext, useState, useEffect, ReactNode, useCallback } from 'react';
import { Aula, Anuncio, DataContextType } from '../types';

// Função para determinar a URL da API dinamicamente
const getApiUrl = () => {
  // 1. Tenta pegar a URL definida nas variáveis de ambiente (se houver)
  const envUrl = (import.meta as any).env?.VITE_API_URL;
  if (envUrl) return envUrl;

  // 2. Se não houver variável de ambiente, constrói a URL baseada no endereço que está no navegador.
  // Isso permite que, se você acessar via "192.168.1.X:5173", o app procure a API em "192.168.1.X:3001".
  // Funciona tanto para localhost quanto para acesso via rede local (WiFi/LAN).
  const hostname = window.location.hostname;
  return `http://${hostname}:3001`;
};

const API_URL = getApiUrl();

export const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [aulas, setAulas] = useState<Aula[]>([]);
  const [anuncio, setAnuncioState] = useState<Anuncio>({ type: null, src: null });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Função para buscar dados do servidor
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/api/data`);
      if (!response.ok) throw new Error('Falha na comunicação com o servidor');

      const data = await response.json();
      setAulas(data.aulas || []);
      setAnuncioState(data.anuncio || { type: null, src: null });
      setError(null);
    } catch (err) {
      console.error(err);
      setError(`Falha ao conectar em ${API_URL}. Verifique se o server.js está rodando e se o firewall permite a porta 3001.`);
    } finally {
      setLoading(false);
    }
  }, []);

  // Carregar dados ao iniciar
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addAula = useCallback(async (aula: Omit<Aula, 'id'>) => {
    try {
      const response = await fetch(`${API_URL}/api/aulas`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(aula),
      });
      if (!response.ok) throw new Error('Erro ao adicionar aula');

      // Atualiza estado local com a resposta do servidor para garantir sincronia
      const updatedAulas = await response.json();
      setAulas(updatedAulas); // O backend retorna a lista completa atualizada ou podemos apenas refazer o fetch
      // fetchData(); // Opcional: recarregar tudo
    } catch (err) {
      console.error(err);
      alert('Erro ao salvar aula no servidor.');
    }
  }, []);

  const updateAulasFromCSV = useCallback(async (data: Omit<Aula, 'id'>[]) => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/api/aulas/bulk`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error('Erro ao importar CSV');

      const updatedAulas = await response.json();
      setAulas(updatedAulas);
    } catch (err) {
      console.error(err);
      alert('Erro ao processar CSV no servidor.');
    } finally {
      setLoading(false);
    }
  }, []);

  const clearAulas = useCallback(async () => {
    try {
      if(!confirm("Tem certeza que deseja apagar todas as aulas do servidor?")) return;

      const response = await fetch(`${API_URL}/api/aulas`, {
        method: 'DELETE',
      });
      if (!response.ok) throw new Error('Erro ao limpar aulas');
      setAulas([]);
    } catch (err) {
      console.error(err);
      alert('Erro ao limpar dados.');
    }
  }, []);

  const setAnuncio = useCallback(async (newAnuncio: Anuncio) => {
    try {
      // Otimisticamente atualiza a UI
      setAnuncioState(newAnuncio);

      const response = await fetch(`${API_URL}/api/anuncio`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newAnuncio),
      });
      if (!response.ok) throw new Error('Erro ao atualizar anúncio');
    } catch (err) {
      console.error(err);
      alert('Erro ao salvar anúncio no servidor.');
    }
  }, []);

  return (
    <DataContext.Provider value={{ aulas, anuncio, loading, error, addAula, updateAulasFromCSV, clearAulas, setAnuncio }}>
      {children}
    </DataContext.Provider>
  );
};

