const DashboardScreen: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const context = useContext(DataContext);
    const [displayAulas, setDisplayAulas] = useState<Aula[]>([]);
    const [currentShift, setCurrentShift] = useState<string>('Manhã');
    const containerRef = useRef<HTMLDivElement>(null);

    const toggleFullScreen = () => {
        if (!document.fullscreenElement) {
            document.documentElement.requestFullscreen().catch(err => {
                console.log(`Erro ao ativar tela cheia: ${err.message}`);
            });
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
        }
    };

    useEffect(() => {
        const updateShift = () => {
            const now = new Date();
            const totalMinutes = now.getHours() * 60 + now.getMinutes();

            if (totalMinutes < 720) { 
                setCurrentShift('Manhã');
            } else if (totalMinutes < 1080) {
                setCurrentShift('Tarde');
            } else {
                setCurrentShift('Noite');
            }
        };

        updateShift();
        const interval = setInterval(updateShift, 60000);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (context && !context.loading) {
            const filtered = context.aulas.filter(aula => {
                const aulaTurno = aula.turno?.toLowerCase();
                const currShift = currentShift.toLowerCase();
                return aulaTurno === currShift;
            });
            setDisplayAulas(filtered);
        }
    }, [context, currentShift]);

    if (!context) {
        return <div className="text-red-500 p-10">Erro: Contexto não encontrado.</div>;
    }

    const { loading, error, anuncio } = context;
    const hasAnuncio = anuncio && anuncio.src;

    return (
        // Container Principal
        <div ref={containerRef} className="h-screen w-screen overflow-hidden bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-[#1a1c2e] via-[#0f1016] to-[#000000] text-white flex flex-col font-sans">

            <Header currentShift={currentShift} onFullscreen={toggleFullScreen} />

            {/* Área de Conteúdo: Tudo na mesma "tela", dividido apenas por colunas flexíveis */}
            <main className="flex-1 flex overflow-hidden relative p-6 pt-2 gap-6">

                {/* Coluna da Esquerda: Lista de Aulas */}
                <div className={`flex flex-col h-full overflow-hidden transition-all duration-500 rounded-2xl ${hasAnuncio ? 'w-[65%]' : 'w-full'}`}>

                    {/* Scroll Container para os cards */}
                    <div className="flex-1 overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent pb-20">

                        {error && (
                            <div className="bg-red-500/20 border border-red-500/50 text-red-200 p-6 rounded-xl text-center mb-8 animate-pulse shadow-lg shadow-red-900/20">
                                {error}
                            </div>
                        )}

                        {loading ? (
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
                                {Array.from({ length: 6 }).map((_, i) => <SkeletonCard key={i} />)}
                            </div>
                        ) : displayAulas.length > 0 ? (
                            <div className={`grid gap-6 ${hasAnuncio ? 'grid-cols-1 md:grid-cols-2 xl:grid-cols-2 2xl:grid-cols-3' : 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'}`}>
                                {displayAulas.map((aula) => <ClassCard key={aula.id} aula={aula} />)}
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-white/30 space-y-6 min-h-[60vh] bg-white/5 rounded-3xl border border-white/5 backdrop-blur-sm">
                                <div className="p-6 bg-black/20 rounded-full">
                                    <ClockIcon className="w-16 h-16 stroke-1 opacity-50" />
                                </div>
                                <div className="text-center">
                                    <h2 className="text-3xl font-light text-white/60">Sem aulas no momento</h2>
                                    <p className="text-lg text-white/40 mt-2">Turno atual: <span className="text-[#ff6600] font-bold">{currentShift}</span></p>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Coluna da Direita: Card de Anúncio Flutuante */}
                {hasAnuncio && (
                    <aside className="w-[35%] h-full hidden lg:block pb-6">
                        {/* Note que removi o padding extra e a borda lateral. 
                            Agora ele é um elemento irmão da lista de aulas. */}
                        <AnnouncementPanel anuncio={anuncio} />
                    </aside>
                )}
            </main>

            {/* Botão de Admin Flutuante Discreto */}
            <button
                onClick={onAdminClick}
                className="fixed bottom-6 left-6 text-white/20 hover:text-[#ff6600] hover:bg-white/10 p-3 rounded-full transition-all duration-300 z-50 group backdrop-blur-md border border-transparent hover:border-white/10"
                title="Administração"
            >
                <SettingsIcon className="w-6 h-6 transform group-hover:rotate-90 transition-transform duration-500" />
            </button>
        </div>
    );
};

export default DashboardScreen;

