                                <div className="overflow-x-auto">
                                    <table className="w-full text-xs text-left text-white/70">
                                        <thead className="text-white/50 bg-white/5 uppercase">
                                            <tr>
                                                <th className="px-2 py-1">Data</th>
                                                <th className="px-2 py-1">Sala</th>
                                                <th className="px-2 py-1">Matéria</th>
                                                <th className="px-2 py-1">Início</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {importedPreview.map((aula, i) => (
                                                <tr key={i} className="border-b border-white/5">
                                                    <td className="px-2 py-1">{aula.data}</td>
                                                    <td className="px-2 py-1 truncate max-w-[80px]">{aula.sala}</td>
                                                    <td className="px-2 py-1 truncate max-w-[120px]">{aula.unidade_curricular}</td>
                                                    <td className="px-2 py-1">{aula.inicio}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Media Upload */}
                    <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                        <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><CameraIcon /> Mídia para o Painel</h2>
                        <input type="file" accept="image/*,video/*" onChange={handleMediaUpload} className="w-full text-sm text-white/70 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-[#ff6600] file:text-white hover:file:bg-[#ff8533]"/>
                        {mediaPreview && (
                            <div className="mt-4 border border-white/20 rounded-lg overflow-hidden">
                                {mediaType === 'image' ? <img src={mediaPreview} alt="Preview" /> : <video src={mediaPreview} controls className="w-full" />}
                            </div>
                        )}
                        <button onClick={handleUpdateAnuncio} className="mt-4 w-full bg-[#ff6600] text-white font-bold py-2 rounded-lg hover:bg-[#ff8533] transition-colors duration-200">Atualizar Anúncio</button>
                    </div>
                </div>

                {/* Coluna de Ações Manuais */}
                <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                    <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><PlusCircleIcon /> Cadastro Manual de Aula</h2>
                    <form onSubmit={handleAddAula} className="space-y-3">
                        <input name="data" value={newAula.data} onChange={handleInputChange} placeholder="Data (DD/MM/AAAA)" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <input name="sala" value={newAula.sala} onChange={handleInputChange} placeholder="Ambiente (Ex: Lab 01)" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <input name="turma" value={newAula.turma} onChange={handleInputChange} placeholder="Turma" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <input name="instrutor" value={newAula.instrutor} onChange={handleInputChange} placeholder="Instrutor" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <input name="unidade_curricular" value={newAula.unidade_curricular} onChange={handleInputChange} placeholder="Unidade Curricular" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                        <div className="flex gap-3">
                            <div className="w-1/2">
                                <label className="text-xs text-white/50 ml-1">Início</label>
                                <input name="inicio" value={newAula.inicio} onChange={handleInputChange} type="time" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                            </div>
                            <div className="w-1/2">
                                <label className="text-xs text-white/50 ml-1">Fim</label>
                                <input name="fim" value={newAula.fim} onChange={handleInputChange} type="time" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-[#ff6600]" />
                            </div>
                        </div>
                        <button type="submit" className="w-full bg-green-600 text-white font-bold py-2 rounded-lg hover:bg-green-700 transition-colors duration-200">Adicionar Aula</button>
                    </form>

                    <div className="mt-8 pt-6 border-t border-white/20">
                         <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><TrashIcon /> Ações Gerais</h2>
                        <button onClick={context.clearAulas} className="w-full bg-red-600 text-white font-bold py-2 rounded-lg hover:bg-red-700 transition-colors duration-200">Limpar Todas as Aulas</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AdminScreen;

import React, { useContext, useEffect, useState, useRef } from 'react';
import { DataContext } from '../context/DataContext';
import useCurrentTime from '../hooks/useCurrentTime';
import { Anuncio, Aula } from '../types';
import { BuildingIcon, UsersIcon, UserTieIcon, BookOpenIcon, ClockIcon, SettingsIcon } from './Icons';

// Icone de Tela Cheia
const MaximizeIcon: React.FC<{ className?: string }> = ({ className }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M8 3H5a2 2 0 0 0-2 2v3"/><path d="M21 8V5a2 2 0 0 0-2-2h-3"/><path d="M3 16v3a2 2 0 0 0 2 2h3"/><path d="M16 21h3a2 2 0 0 0 2-2v-3"/></svg>
);

// Header Component
const Header: React.FC<{ currentShift: string; onFullscreen: () => void }> = ({ currentShift, onFullscreen }) => {
    const { formattedDate, formattedTime } = useCurrentTime();

    let shiftColor = 'text-white/80';
    if (currentShift === 'Manhã') shiftColor = 'text-yellow-400';
    if (currentShift === 'Tarde') shiftColor = 'text-orange-500';
    if (currentShift === 'Noite') shiftColor = 'text-indigo-400';

    return (
        <header className="flex-none bg-black/10 backdrop-blur-sm p-4 flex justify-between items-center text-white px-8 h-20 z-20 relative border-b border-white/5">
            <div className="text-sm font-light tracking-widest uppercase text-white/50 flex flex-col">
                <span>Painel de Aulas</span>
                <button onClick={onFullscreen} className="text-xs hover:text-[#ff6600] flex items-center gap-1 mt-1" title="Entrar em Tela Cheia">
                    <MaximizeIcon className="w-3 h-3" /> Tela Cheia
                </button>
            </div>

            <div className="absolute left-1/2 transform -translate-x-1/2 text-center">
                 <h1 className="text-2xl md:text-3xl font-bold tracking-wider leading-none drop-shadow-lg">
                    {formattedTime}
                </h1>
                <span className="text-sm font-light text-white/70 tracking-widest uppercase">
                    {formattedDate}
                </span>
            </div>

            <div className={`text-lg font-bold tracking-wide uppercase flex items-center gap-2 ${shiftColor}`}>
                <span className="bg-black/40 px-4 py-1 rounded-full text-sm backdrop-blur-md border border-white/10 shadow-lg">
                    Turno: {currentShift}
                </span>
            </div>
        </header>
    );
};

// Class Card Component
const ClassCard: React.FC<{ aula: Aula }> = ({ aula }) => (
    <div className="bg-white/5 backdrop-blur-md border border-white/10 rounded-xl p-4 shadow-lg transition-all duration-300 hover:bg-white/10 hover:border-white/20 hover:scale-[1.01] flex flex-col gap-2 relative group h-full">
        <div className="absolute top-3 right-3 opacity-60 text-[10px] font-bold uppercase tracking-widest bg-black/20 border border-white/10 px-2 py-0.5 rounded-full">
            {aula.turno}
        </div>

        <div className="flex items-center gap-3 mb-1">
            <div className="p-2 bg-gradient-to-br from-[#ff6600] to-[#cc5200] rounded-lg text-white shadow-lg shadow-orange-900/20">
                <BuildingIcon className="w-5 h-5" />
            </div>
            <div className="overflow-hidden">
                <h2 className="text-lg font-bold text-white truncate leading-tight tracking-tight">{aula.sala}</h2>
            </div>
        </div>

        <div className="space-y-2 mt-2 flex-1">
            <div className="bg-black/20 rounded-md p-2 flex items-center gap-2 border border-white/5">
                <UsersIcon className="w-4 h-4 text-white/60" />
                <span className="text-sm text-white/90 font-medium truncate">{aula.turma}</span>
            </div>
            <div className="bg-black/20 rounded-md p-2 flex items-center gap-2 border border-white/5">
                <UserTieIcon className="w-4 h-4 text-white/60" />
                <span className="text-sm text-white/90 truncate">{aula.instrutor}</span>
            </div>
            <div className="bg-black/20 rounded-md p-2 flex items-center gap-2 border border-white/5">
                <BookOpenIcon className="w-4 h-4 text-white/60" />
                {/* Alterado para line-clamp-2 para suportar nomes longos do CSV */}
                <span className="text-sm text-white/90 line-clamp-2 leading-snug" title={aula.unidade_curricular}>{aula.unidade_curricular}</span>
            </div>
        </div>

        <div className="mt-3 pt-2 border-t border-white/10 flex justify-between items-center text-[#ff6600]">
            <span className="text-[10px] uppercase font-bold text-white/30 tracking-wider">Horário</span>
            <div className="flex items-center gap-1 font-bold bg-[#ff6600]/10 px-2 py-0.5 rounded-full text-xs">
                <ClockIcon className="w-3 h-3" /> {aula.inicio} - {aula.fim}
            </div>
        </div>
    </div>
);

// Skeleton Card
const SkeletonCard: React.FC = () => (
    <div className="bg-white/5 border border-white/10 rounded-xl p-4 shadow-lg animate-pulse h-48">
        <div className="flex gap-3 mb-4">
            <div className="w-10 h-10 bg-white/10 rounded-lg"></div>
            <div className="h-6 bg-white/10 rounded w-1/2 mt-2"></div>
        </div>
        <div className="space-y-2">
            <div className="h-8 bg-white/10 rounded w-full"></div>
            <div className="h-8 bg-white/10 rounded w-full"></div>
            <div className="h-8 bg-white/10 rounded w-full"></div>
        </div>
    </div>
);

// Announcement Panel
const AnnouncementPanel: React.FC<{ anuncio: Anuncio }> = ({ anuncio }) => {
    if (!anuncio.src) return null;

    return (
        <div className="w-full h-full relative overflow-hidden flex items-center justify-center bg-black/40">
            <div className="absolute inset-0 opacity-40 blur-3xl transform scale-110">
                {anuncio.type === 'image' ? (
                     <img src={anuncio.src} alt="" className="w-full h-full object-cover" />
                ) : (
                    <video src={anuncio.src} muted className="w-full h-full object-cover" />
                )}
            </div>
            <div className="absolute inset-0 bg-black/30"></div>
            <div className="relative z-10 w-full h-full flex items-center justify-center p-6">
                {anuncio.type === 'image' && (
                    <img src={anuncio.src} alt="Anúncio" className="max-w-full max-h-full object-contain drop-shadow-2xl rounded-lg shadow-black/50" />
                )}
                {anuncio.type === 'video' && (
                    <video src={anuncio.src} autoPlay loop muted playsInline className="max-w-full max-h-full object-contain drop-shadow-2xl rounded-lg shadow-black/50"></video>
                )}
            </div>
            <div className="absolute top-6 right-6 z-20 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full border border-white/10 text-xs font-bold uppercase tracking-widest text-white/70">
                Informativo
            </div>
        </div>
    );
};

const DashboardScreen: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const context = useContext(DataContext);
    const [filteredAulas, setFilteredAulas] = useState<Aula[]>([]); // Aulas do dia/turno
    const [visibleAulas, setVisibleAulas] = useState<Aula[]>([]);   // Aulas da página atual
    const [currentShift, setCurrentShift] = useState<string>('Manhã');
    const [page, setPage] = useState(0); // Página atual do carrossel

    const containerRef = useRef<HTMLDivElement>(null);

    const toggleFullScreen = () => {
        if (!document.fullscreenElement) {
            document.documentElement.requestFullscreen().catch(err => {
                console.log(`Erro ao ativar tela cheia: ${err.message}`);
            });
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
        }
    };

    // 1. Atualiza Turno
    useEffect(() => {
        const updateShift = () => {
            const now = new Date();
            const totalMinutes = now.getHours() * 60 + now.getMinutes();

            if (totalMinutes < 720) { 
                setCurrentShift('Manhã');
            } else if (totalMinutes < 1080) {
                setCurrentShift('Tarde');
            } else {
                setCurrentShift('Noite');
            }
        };
        updateShift();
        const interval = setInterval(updateShift, 60000);
        return () => clearInterval(interval);
    }, []);

    // 2. Filtra Aulas (Hoje + Turno)
    useEffect(() => {
        if (context && !context.loading) {
            const today = new Date().toLocaleDateString('pt-BR'); // Formato "DD/MM/YYYY"

            const filtered = context.aulas.filter(aula => {
                const aulaData = aula.data || ''; // Previne erro se não tiver data
                const aulaTurno = aula.turno?.toLowerCase();
                const currShift = currentShift.toLowerCase();

                // Verifica Data E Turno
                return aulaData === today && aulaTurno === currShift;
            });
            setFilteredAulas(filtered);
            setPage(0); // Reseta paginação ao mudar filtro
        }
    }, [context, currentShift]);

    // 3. Paginação Automática (Carrossel)
    const { anuncio } = context || {};
    const hasAnuncio = anuncio && anuncio.src;

    // Define quantos itens cabem por página. 
    // Com Anúncio (layout 60/40), cabem ~6 cards (3x2 ou 2x3).
    // Sem Anúncio (tela cheia), cabem ~8 ou 10 cards.
    const ITEMS_PER_PAGE = hasAnuncio ? 6 : 8;

    useEffect(() => {
        const totalPages = Math.ceil(filteredAulas.length / ITEMS_PER_PAGE);

        // Define as aulas visíveis agora
        const start = page * ITEMS_PER_PAGE;
        const end = start + ITEMS_PER_PAGE;
        setVisibleAulas(filteredAulas.slice(start, end));

        // Configura o timer para rodar a página
        if (totalPages > 1) {
            const interval = setInterval(() => {
                setPage(prevPage => (prevPage + 1) % totalPages);
            }, 15000); // Troca a cada 15 segundos
            return () => clearInterval(interval);
        }
    }, [filteredAulas, page, ITEMS_PER_PAGE]);


    if (!context) {
        return <div className="text-red-500 p-10">Erro: Contexto não encontrado.</div>;
    }

    const { loading, error } = context;

    return (
        <div ref={containerRef} className="h-screen w-screen overflow-hidden bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-[#1a1c2e] via-[#0f1016] to-[#000000] text-white flex flex-col font-sans">

            <Header currentShift={currentShift} onFullscreen={toggleFullScreen} />

            <main className="flex-1 overflow-hidden p-6 relative flex flex-col">

                <div className="flex-1 w-full flex bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl shadow-2xl overflow-hidden relative">

                    {/* Lista de Aulas */}
                    <div className={`flex flex-col h-full relative ${hasAnuncio ? 'w-[60%] border-r border-white/10' : 'w-full'}`}>

                        {/* Área de Cards - Sem Scroll (overflow-hidden) */}
                        <div className="flex-1 p-6 overflow-hidden flex flex-col justify-center">

                            {error && (
                                <div className="bg-red-500/20 border border-red-500/50 text-red-200 p-6 rounded-xl text-center mb-8 animate-pulse shadow-lg shadow-red-900/20">
                                    {error}
                                </div>
                            )}

                            {loading ? (
                                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5 h-full content-center">
                                    {Array.from({ length: 6 }).map((_, i) => <SkeletonCard key={i} />)}
                                </div>
                            ) : visibleAulas.length > 0 ? (
                                <>
                                    <div className={`grid gap-5 h-full content-start ${hasAnuncio ? 'grid-cols-1 md:grid-cols-2 2xl:grid-cols-2' : 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'}`}>
                                        {visibleAulas.map((aula) => <ClassCard key={aula.id} aula={aula} />)}
                                    </div>

                                    {/* Indicador de Paginação (se houver mais de 1 página) */}
                                    {filteredAulas.length > ITEMS_PER_PAGE && (
                                        <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-2">
                                            {Array.from({ length: Math.ceil(filteredAulas.length / ITEMS_PER_PAGE) }).map((_, i) => (
                                                <div 
                                                    key={i} 
                                                    className={`h-1.5 rounded-full transition-all duration-300 ${i === page ? 'w-8 bg-[#ff6600]' : 'w-2 bg-white/20'}`}
                                                />
                                            ))}
                                        </div>
                                    )}
                                </>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-white/30 space-y-6">
                                    <div className="p-6 bg-black/20 rounded-full">
                                        <ClockIcon className="w-16 h-16 stroke-1 opacity-50" />
                                    </div>
                                    <div className="text-center">
                                        <h2 className="text-3xl font-light text-white/60">Sem aulas hoje neste turno</h2>
                                        <p className="text-lg text-white/40 mt-2">
                                            Data: {new Date().toLocaleDateString('pt-BR')} | Turno: <span className="text-[#ff6600] font-bold">{currentShift}</span>
                                        </p>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Anúncio */}
                    {hasAnuncio && (
                        <aside className="w-[40%] h-full hidden lg:block bg-black/20">
                            <AnnouncementPanel anuncio={anuncio} />
                        </aside>
                    )}
                </div>
            </main>

            <button
                onClick={onAdminClick}
                className="fixed bottom-4 left-4 text-white/20 hover:text-[#ff6600] hover:bg-white/10 p-3 rounded-full transition-all duration-300 z-50 group backdrop-blur-md border border-transparent hover:border-white/10"
                title="Administração"
            >
                <SettingsIcon className="w-5 h-5 transform group-hover:rotate-90 transition-transform duration-500" />
            </button>
        </div>
    );
};

export default DashboardScreen;

