```tsx
import React, { useState } from 'react';
import { LoginModal } from './LoginModal'; // Ensure this path is correct
import AdminPanel from './AdminPanel';

const AdminScreen: React.FC<{ onReturnToDashboard: () => void }> = ({ onReturnToDashboard }) => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [loginError, setLoginError] = useState<string | null>(null);

    const handleLogin = (success: boolean, error?: string) => {
        if (success) {
            setIsAuthenticated(true);
            setLoginError(null);
        } else {
            setIsAuthenticated(false);
            setLoginError(error || "Login failed");
        }
    };

    const handleLogout = () => {
        setIsAuthenticated(false);
        onReturnToDashboard();
    };

    if (isAuthenticated) {
        return <AdminPanel onLogout={handleLogout} />;
    } else {
        return (
            <LoginModal
                onLogin={handleLogin}
                loginError={loginError}
            />
        );
    }
};

export default AdminScreen;
```

