import express from 'express';
import cors from 'cors';
import bodyParser from 'body-parser';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

// Configuração para __dirname em ES Modules
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = 3001;
const DB_FILE = path.join(__dirname, 'db.json');

// Aumentando limite para suportar imagens/vídeos grandes em base64
// Vídeos base64 são 33% maiores que o binário, 500mb garante uploads seguros
app.use(bodyParser.json({ limit: '500mb' }));
app.use(bodyParser.urlencoded({ limit: '500mb', extended: true }));
app.use(cors());

// Dados iniciais (Mock) caso o arquivo não exista
const INITIAL_DATA = {
  aulas: [
    { id: '1', sala: 'Lab 01 - Redes', turma: 'Téc. Redes 2023.2', instrutor: 'Carlos Silva', unidade_curricular: 'Administração de Servidores', inicio: '08:00', fim: '12:00', turno: 'Manhã', data: new Date().toLocaleDateString('pt-BR') },
    { id: '2', sala: 'Lab 02 - Programação', turma: 'Téc. ADS 2024.1', instrutor: 'Ana Pereira', unidade_curricular: 'Lógica de Programação', inicio: '08:00', fim: '12:00', turno: 'Manhã', data: new Date().toLocaleDateString('pt-BR') }
  ],
  anuncio: { type: null, src: null }
};

// Função auxiliar para ler o banco de dados
const readDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify(INITIAL_DATA, null, 2));
    return INITIAL_DATA;
  }
  try {
    const data = fs.readFileSync(DB_FILE, 'utf8');
    return JSON.parse(data);
  } catch (error) {
    console.error("Erro ao ler DB:", error);
    return INITIAL_DATA;
  }
};

// Função auxiliar para escrever no banco de dados
const writeDB = (data) => {
  fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
};

// --- ROTAS ---

// GET: Retorna todos os dados
app.get('/api/data', (req, res) => {
  const data = readDB();
  // Simular pequeno delay de rede para UI
  setTimeout(() => res.json(data), 300);
});

// POST: Adicionar uma aula
app.post('/api/aulas', (req, res) => {
  const db = readDB();
  const novaAula = { ...req.body, id: new Date().toISOString() };
  db.aulas.push(novaAula);
  writeDB(db);
  res.json(db.aulas);
});

// POST: Atualizar aulas em massa (CSV)
app.post('/api/aulas/bulk', (req, res) => {
  const db = readDB();
  const novasAulas = req.body.map(d => ({ 
    ...d, 
    id: `${d.sala}-${d.turma}-${Math.random().toString(36).substr(2, 9)}` 
  }));
  db.aulas = novasAulas;
  writeDB(db);
  res.json(db.aulas);
});

// PUT: Atualizar uma aula específica
app.put('/api/aulas/:id', (req, res) => {
  const db = readDB();
  const { id } = req.params;
  const index = db.aulas.findIndex(a => a.id === id);

  if (index !== -1) {
    db.aulas[index] = { ...db.aulas[index], ...req.body };
    writeDB(db);
    res.json(db.aulas);
  } else {
    res.status(404).json({ message: 'Aula não encontrada' });
  }
});

// DELETE: Limpar todas as aulas
app.delete('/api/aulas', (req, res) => {
  const db = readDB();
  db.aulas = [];
  writeDB(db);
  res.json(db.aulas);
});

// DELETE: Deletar aula específica (opcional, mas boa prática)
app.delete('/api/aulas/:id', (req, res) => {
  const db = readDB();
  const { id } = req.params;
  db.aulas = db.aulas.filter(a => a.id !== id);
  writeDB(db);
  res.json(db.aulas);
});

// POST: Atualizar Anúncio
app.post('/api/anuncio', (req, res) => {
  const db = readDB();
  db.anuncio = req.body;
  writeDB(db);
  res.json(db.anuncio);
});

app.listen(PORT, () => {
  console.log(`Servidor rodando em http://localhost:${PORT}`);
  console.log(`Certifique-se de configurar VITE_API_URL=http://localhost:${PORT} no seu .env.local ou o front usará este padrão.`);
});

export interface Aula {
  id: string;
  data: string; // Formato DD/MM/YYYY
  sala: string;
  turma: string;
  instrutor: string;
  unidade_curricular: string;
  inicio: string;
  fim: string;
  turno?: string;
}

export interface Anuncio {
  type: 'image' | 'video' | null;
  src: string | null;
}

export interface DataContextType {
  aulas: Aula[];
  anuncio: Anuncio;
  loading: boolean;
  error: string | null;
  addAula: (aula: Omit<Aula, 'id'>) => void;
  updateAulasFromCSV: (data: Omit<Aula, 'id'>[]) => void;
  updateAula: (id: string, aula: Partial<Aula>) => Promise<void>;
  deleteAula: (id: string) => Promise<void>;
  clearAulas: () => void;
  setAnuncio: (anuncio: Anuncio) => void;
}

import React, { createContext, useState, useEffect, ReactNode, useCallback } from 'react';
import { Aula, Anuncio, DataContextType } from '../types';

// Função para determinar a URL da API dinamicamente
const getApiUrl = () => {
  const envUrl = (import.meta as any).env?.VITE_API_URL;
  if (envUrl) return envUrl;
  const hostname = window.location.hostname;
  return `http://${hostname}:3001`;
};

const API_URL = getApiUrl();

export const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [aulas, setAulas] = useState<Aula[]>([]);
  const [anuncio, setAnuncioState] = useState<Anuncio>({ type: null, src: null });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Função para buscar dados do servidor
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/api/data`);
      if (!response.ok) throw new Error('Falha na comunicação com o servidor');

      const data = await response.json();
      setAulas(data.aulas || []);
      setAnuncioState(data.anuncio || { type: null, src: null });
      setError(null);
    } catch (err) {
      console.error(err);
      setError(`Falha ao conectar em ${API_URL}. Verifique se o server.js está rodando.`);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addAula = useCallback(async (aula: Omit<Aula, 'id'>) => {
    try {
      const response = await fetch(`${API_URL}/api/aulas`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(aula),
      });
      if (!response.ok) throw new Error('Erro ao adicionar aula');
      const updatedAulas = await response.json();
      setAulas(updatedAulas);
    } catch (err) {
      console.error(err);
      alert('Erro ao salvar aula no servidor.');
    }
  }, []);

  const updateAulasFromCSV = useCallback(async (data: Omit<Aula, 'id'>[]) => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/api/aulas/bulk`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error('Erro ao importar CSV');
      const updatedAulas = await response.json();
      setAulas(updatedAulas);
    } catch (err) {
      console.error(err);
      alert('Erro ao processar CSV no servidor.');
    } finally {
      setLoading(false);
    }
  }, []);

  const updateAula = useCallback(async (id: string, aulaData: Partial<Aula>) => {
      try {
          const response = await fetch(`${API_URL}/api/aulas/${id}`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(aulaData),
          });
          if (!response.ok) throw new Error('Erro ao atualizar aula');
          const updatedAulas = await response.json();
          setAulas(updatedAulas);
      } catch (err) {
          console.error(err);
          alert('Erro ao atualizar aula.');
      }
  }, []);

  const deleteAula = useCallback(async (id: string) => {
    try {
        const response = await fetch(`${API_URL}/api/aulas/${id}`, {
            method: 'DELETE',
        });
        if (!response.ok) throw new Error('Erro ao deletar aula');
        const updatedAulas = await response.json();
        setAulas(updatedAulas);
    } catch (err) {
        console.error(err);
        alert('Erro ao deletar aula.');
    }
  }, []);

  const clearAulas = useCallback(async () => {
    try {
      if(!confirm("Tem certeza que deseja apagar todas as aulas do servidor?")) return;
      const response = await fetch(`${API_URL}/api/aulas`, {
        method: 'DELETE',
      });
      if (!response.ok) throw new Error('Erro ao limpar aulas');
      setAulas([]);
    } catch (err) {
      console.error(err);
      alert('Erro ao limpar dados.');
    }
  }, []);

  const setAnuncio = useCallback(async (newAnuncio: Anuncio) => {
    try {
      setAnuncioState(newAnuncio);
      const response = await fetch(`${API_URL}/api/anuncio`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newAnuncio),
      });
      if (!response.ok) throw new Error('Erro ao atualizar anúncio');
    } catch (err) {
      console.error(err);
      alert('Erro ao salvar anúncio no servidor.');
    }
  }, []);

  return (
    <DataContext.Provider value={{ aulas, anuncio, loading, error, addAula, updateAulasFromCSV, updateAula, deleteAula, clearAulas, setAnuncio }}>
      {children}
    </DataContext.Provider>
  );
};

