const DashboardScreen: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const context = useContext(DataContext);
    const [filteredAulas, setFilteredAulas] = useState<Aula[]>([]); // Aulas do dia/turno
    const [visibleAulas, setVisibleAulas] = useState<Aula[]>([]);   // Aulas da página atual
    const [currentShift, setCurrentShift] = useState<string>('Manhã');
    const [page, setPage] = useState(0); // Página atual do carrossel

    const containerRef = useRef<HTMLDivElement>(null);

    const toggleFullScreen = () => {
        if (!document.fullscreenElement) {
            document.documentElement.requestFullscreen().catch(err => {
                console.log(`Erro ao ativar tela cheia: ${err.message}`);
            });
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
        }
    };

    // 1. Atualiza Turno
    useEffect(() => {
        const updateShift = () => {
            const now = new Date();
            const totalMinutes = now.getHours() * 60 + now.getMinutes();

            if (totalMinutes < 720) { 
                setCurrentShift('Manhã');
            } else if (totalMinutes < 1080) {
                setCurrentShift('Tarde');
            } else {
                setCurrentShift('Noite');
            }
        };
        updateShift();
        const interval = setInterval(updateShift, 60000);
        return () => clearInterval(interval);
    }, []);

    // 2. Filtra Aulas (Hoje + Turno)
    useEffect(() => {
        if (context && !context.loading) {
            const today = new Date().toLocaleDateString('pt-BR'); // Formato "DD/MM/YYYY"

            const filtered = context.aulas.filter(aula => {
                const aulaData = aula.data || ''; // Previne erro se não tiver data
                const aulaTurno = aula.turno?.toLowerCase();
                const currShift = currentShift.toLowerCase();

                // Verifica Data E Turno
                return aulaData === today && aulaTurno === currShift;
            });
            setFilteredAulas(filtered);
            setPage(0); // Reseta paginação ao mudar filtro
        }
    }, [context, currentShift]);

    // 3. Paginação Automática (Carrossel)
    const { anuncio } = context || {};
    const hasAnuncio = anuncio && anuncio.src;

    // Define quantos itens cabem por página
    const ITEMS_PER_PAGE = hasAnuncio ? 8 : 12;

    useEffect(() => {
        const totalPages = Math.ceil(filteredAulas.length / ITEMS_PER_PAGE);

        // Define as aulas visíveis agora
        const start = page * ITEMS_PER_PAGE;
        const end = start + ITEMS_PER_PAGE;
        setVisibleAulas(filteredAulas.slice(start, end));

        // Configura o timer para rodar a página
        if (totalPages > 1) {
            const interval = setInterval(() => {
                setPage(prevPage => (prevPage + 1) % totalPages);
            }, 15000); // Troca a cada 15 segundos
            return () => clearInterval(interval);
        }
    }, [filteredAulas, page, ITEMS_PER_PAGE]);


    if (!context) {
        return <div className="text-red-500 p-10">Erro: Contexto não encontrado.</div>;
    }

    const { loading, error } = context;

    return (
        <div ref={containerRef} className="h-screen w-screen overflow-hidden bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-[#1a1c2e] via-[#0f1016] to-[#000000] text-white flex flex-col font-sans">

            <Header currentShift={currentShift} onFullscreen={toggleFullScreen} />

            <main className="flex-1 overflow-hidden p-6 relative flex flex-col">

                <div className="flex-1 w-full flex bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl shadow-2xl overflow-hidden relative">

                    {/* Lista de Aulas */}
                    <div className={`flex flex-col h-full relative ${hasAnuncio ? 'w-[60%] border-r border-white/10' : 'w-full'}`}>

                        {/* Área de Cards - Sem Scroll (overflow-hidden) */}
                        <div className="flex-1 p-6 overflow-hidden flex flex-col justify-center">

                            {error && (
                                <div className="bg-red-500/20 border border-red-500/50 text-red-200 p-6 rounded-xl text-center mb-8 animate-pulse shadow-lg shadow-red-900/20">
                                    {error}
                                </div>
                            )}

                            {loading ? (
                                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5 h-full content-center">
                                    {Array.from({ length: 8 }).map((_, i) => <SkeletonCard key={i} />)}
                                </div>
                            ) : visibleAulas.length > 0 ? (
                                <>
                                    <div className={`grid gap-5 h-full content-start ${hasAnuncio ? 'grid-cols-1 md:grid-cols-2 2xl:grid-cols-2' : 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'}`}>
                                        {visibleAulas.map((aula) => <ClassCard key={aula.id} aula={aula} />)}
                                    </div>

                                    {/* Indicador de Paginação (se houver mais de 1 página) */}
                                    {filteredAulas.length > ITEMS_PER_PAGE && (
                                        <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-2">
                                            {Array.from({ length: Math.ceil(filteredAulas.length / ITEMS_PER_PAGE) }).map((_, i) => (
                                                <div 
                                                    key={i} 
                                                    className={`h-1.5 rounded-full transition-all duration-300 ${i === page ? 'w-8 bg-[#ff6600]' : 'w-2 bg-white/20'}`}
                                                />
                                            ))}
                                        </div>
                                    )}
                                </>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-white/30 space-y-6">
                                    <div className="p-6 bg-black/20 rounded-full">
                                        <ClockIcon className="w-16 h-16 stroke-1 opacity-50" />
                                    </div>
                                    <div className="text-center">
                                        <h2 className="text-3xl font-light text-white/60">Sem aulas hoje neste turno</h2>
                                        <p className="text-lg text-white/40 mt-2">
                                            Data: {new Date().toLocaleDateString('pt-BR')} | Turno: <span className="text-[#ff6600] font-bold">{currentShift}</span>
                                        </p>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Anúncio */}
                    {hasAnuncio && (
                        <aside className="w-[40%] h-full hidden lg:block bg-black/20">
                            <AnnouncementPanel anuncio={anuncio} />
                        </aside>
                    )}
                </div>
            </main>

            <button
                onClick={onAdminClick}
                className="fixed bottom-4 left-4 text-white/20 hover:text-[#ff6600] hover:bg-white/10 p-3 rounded-full transition-all duration-300 z-50 group backdrop-blur-md border border-transparent hover:border-white/10"
                title="Administração"
            >
                <SettingsIcon className="w-5 h-5 transform group-hover:rotate-90 transition-transform duration-500" />
            </button>
        </div>
    );
};

