// Componente de Linha de Aula Editável
const AulaItem: React.FC<{ aula: Aula, onUpdate: (id: string, data: Partial<Aula>) => void, onDelete: (id: string) => void }> = ({ aula, onUpdate, onDelete }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editData, setEditData] = useState<Aula>(aula);

    const handleSave = () => {
        onUpdate(aula.id, editData);
        setIsEditing(false);
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
        setEditData({ ...editData, [e.target.name]: e.target.value });
    };

    if (isEditing) {
        return (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-2 bg-white/10 p-4 rounded-lg items-center border border-[#ff6600]/50 animate-pulse-border">
                <input name="data" value={editData.data} onChange={handleChange} className="bg-black/40 border border-white/20 rounded px-2 py-1 text-xs text-white" placeholder="Data" />
                <input name="inicio" value={editData.inicio} onChange={handleChange} className="bg-black/40 border border-white/20 rounded px-2 py-1 text-xs text-white" placeholder="Início" />
                <input name="turma" value={editData.turma} onChange={handleChange} className="bg-black/40 border border-white/20 rounded px-2 py-1 text-xs text-white" placeholder="Turma" />
                <input name="sala" value={editData.sala} onChange={handleChange} className="bg-black/40 border border-white/20 rounded px-2 py-1 text-xs text-white" placeholder="Sala" />
                <input name="instrutor" value={editData.instrutor} onChange={handleChange} className="bg-black/40 border border-white/20 rounded px-2 py-1 text-xs text-white" placeholder="Instrutor" />
                <div className="flex gap-2 justify-end">
                    <button onClick={handleSave} className="text-green-400 hover:text-green-300 text-xs font-bold uppercase border border-green-400/50 px-2 py-1 rounded">Salvar</button>
                    <button onClick={() => setIsEditing(false)} className="text-red-400 hover:text-red-300 text-xs font-bold uppercase border border-red-400/50 px-2 py-1 rounded">Cancelar</button>
                </div>
            </div>
        )
    }

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-2 bg-white/5 p-4 rounded-lg items-center hover:bg-white/10 transition-colors border border-white/5">
            <div className="text-xs text-white/70 font-mono"><span className="md:hidden font-bold">Data: </span>{aula.data}</div>
            <div className="text-xs text-[#ff6600] font-bold"><span className="md:hidden text-white/50 font-normal">Hora: </span>{aula.inicio} - {aula.fim} <span className="text-white/30 font-normal text-[10px] ml-1">({aula.turno})</span></div>
            <div className="text-xs font-bold text-white truncate"><span className="md:hidden text-white/50 font-normal">Turma: </span>{aula.turma}</div>
            <div className="text-xs text-white/80 truncate"><span className="md:hidden text-white/50 font-normal">Sala: </span>{aula.sala}</div>
            <div className="text-xs text-white/60 truncate"><span className="md:hidden text-white/50 font-normal">Instrutor: </span>{aula.instrutor}</div>
            <div className="flex gap-2 justify-end">
                 <button onClick={() => setIsEditing(true)} className="text-[#ff6600] hover:text-white text-xs font-bold uppercase transition-colors">Editar</button>
                 <button onClick={() => onDelete(aula.id)} className="text-red-500 hover:text-red-400 ml-2" title="Excluir"><TrashIcon className="w-4 h-4" /></button>
            </div>
        </div>
    );
};

// Admin Panel Component
const AdminPanel: React.FC<{ onLogout: () => void }> = ({ onLogout }) => {
    const context = useContext(DataContext);
    const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);
    const [newAula, setNewAula] = useState<Omit<Aula, 'id'>>({ 
        data: new Date().toLocaleDateString('pt-BR'), 
        sala: '', 
        turma: '', 
        instrutor: '', 
        unidade_curricular: '', 
        inicio: '', 
        fim: '' 
    });
    const [mediaPreview, setMediaPreview] = useState<string | null>(null);
    const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);

    const fileInputRef = useRef<HTMLInputElement>(null);

    if (!context) return <p>Erro de contexto.</p>;

    // Ordenação das aulas: Apenas HOJE -> Manhã > Tarde > Noite
    const sortedAulas = useMemo(() => {
        const today = new Date().toLocaleDateString('pt-BR');
        const turnosOrder: { [key: string]: number } = { 'Manhã': 1, 'Tarde': 2, 'Noite': 3 };

        // Filtra apenas as aulas de hoje
        const aulasDeHoje = context.aulas.filter(aula => aula.data === today);

        return [...aulasDeHoje].sort((a, b) => {
            const turnoA = a.turno || calcularTurno(a.inicio);
            const turnoB = b.turno || calcularTurno(b.inicio);

            const orderA = turnosOrder[turnoA] || 4;
            const orderB = turnosOrder[turnoB] || 4;

            if (orderA !== orderB) return orderA - orderB;

            return a.inicio.localeCompare(b.inicio);
        });
    }, [context.aulas]);

    const handleCSVUpload = (e: ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const text = event.target?.result as string;
            try {
                const parseCsvRow = (row: string): string[] => {
                    const result: string[] = [];
                    let current = '';
                    let inQuotes = false;
                    for (let i = 0; i < row.length; i++) {
                        const char = row[i];
                        if (char === '"') {
                            if (inQuotes && row[i + 1] === '"') { current += '"'; i++; } else { inQuotes = !inQuotes; }
                        } else if (char === ',' && !inQuotes) {
                            result.push(current.trim().replace(/^"|"$/g, ''));
                            current = '';
                        } else { current += char; }
                    }
                    result.push(current.trim().replace(/^"|"$/g, ''));
                    return result;
                };

                const rows = text.split('\n').filter(row => row.trim() !== '');
                if (rows.length < 2) throw new Error('Arquivo CSV inválido.');

                const headerRow = rows.shift()!.trim();
                const headers = parseCsvRow(headerRow);

                const headerMapping: { [key: string]: string } = {
                    data: 'Data', sala: 'Ambiente Educacional / Justificativa', turma: 'Turma / Tipo Reserva', instrutor: 'Instrutor/Ambiente Reserva', unidade_curricular: 'Unidade Curricular / Solicitante', inicio: 'Inicio', fim: 'Fim', turno: 'Turno'
                };

                const colIndices: { [key: string]: number } = {};
                for (const key of ['data', 'sala', 'turma', 'instrutor', 'unidade_curricular', 'inicio', 'fim']) {
                    const idx = headers.findIndex(h => h.trim() === headerMapping[key]);
                    if (idx === -1) throw new Error(`Coluna obrigatória não encontrada: "${headerMapping[key]}".`);
                    colIndices[key] = idx;
                }
                const turnoIdx = headers.findIndex(h => h.trim() === 'Turno' || h.trim() === 'Turno / Periodo');
                if (turnoIdx !== -1) colIndices['turno'] = turnoIdx;

                const data = rows.map((row) => {
                        if (!row.trim()) return null;
                        const values = parseCsvRow(row.trim());
                        if (values.length <= Math.max(...Object.values(colIndices))) return null;

                        const extractTime = (t: string, type: 's'|'e') => {
                            if (!t) return '';
                            const m = t.match(/\d{2}:\d{2}/g);
                            if (!m || m.length === 0) return t.substring(0, 5);
                            return type === 's' ? m[0] : m[m.length - 1];
                        };

                        const inicio = extractTime(values[colIndices.inicio], 's');
                        let turnoFinal = '';
                        if (colIndices['turno'] !== undefined && values[colIndices['turno']]) {
                            turnoFinal = normalizarTurnoCSV(values[colIndices['turno']]) || calcularTurno(inicio);
                        } else {
                            turnoFinal = calcularTurno(inicio);
                        }

                        const aulaData: Omit<Aula, 'id'> = {
                            data: values[colIndices.data] || '',
                            sala: values[colIndices.sala] || '',
                            turma: values[colIndices.turma] || '',
                            instrutor: values[colIndices.instrutor] || '',
                            unidade_curricular: (values[colIndices.unidade_curricular] || '').replace(/\s*\(CH:.*\)/i, '').trim(),
                            inicio: inicio,
                            fim: extractTime(values[colIndices.fim], 'e'),
                            turno: turnoFinal
                        };
                        return (aulaData.sala && aulaData.inicio) ? aulaData : null;
                    }).filter((item): item is Omit<Aula, 'id'> => item !== null);

                if (data.length === 0) throw new Error('Nenhuma linha válida encontrada.');

                context.updateAulasFromCSV(data);
                setToast({ message: `${data.length} aulas importadas com sucesso!`, type: 'success' });
            } catch (err) {
                 setToast({ message: err instanceof Error ? err.message : 'Erro ao processar CSV.', type: 'error' });
            }
        };
        reader.readAsText(file, 'UTF-8');
    };

    const handleMediaUpload = (e: ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onloadend = () => {
            setMediaPreview(reader.result as string);
            setMediaType(file.type.startsWith('image') ? 'image' : 'video');
        };
        reader.readAsDataURL(file);
    };

    const handleUpdateAnuncio = () => {
        if (mediaPreview && mediaType) {
            context.setAnuncio({ src: mediaPreview, type: mediaType });
            setToast({ message: 'Mídia de anúncio atualizada!', type: 'success' });
        } else { setToast({ message: 'Nenhuma mídia selecionada.', type: 'error' }); }
    };

    const handleAddAula = (e: FormEvent) => {
        e.preventDefault();
        if (Object.values(newAula).some(val => typeof val === 'string' && val.trim() === '')) {
            setToast({ message: 'Preencha todos os campos.', type: 'error' }); return;
        }
        context.addAula({ ...newAula, turno: calcularTurno(newAula.inicio) });
        setNewAula({ data: new Date().toLocaleDateString('pt-BR'), sala: '', turma: '', instrutor: '', unidade_curricular: '', inicio: '', fim: '' });
        setToast({ message: 'Aula adicionada!', type: 'success' });
    };

    const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => setNewAula({ ...newAula, [e.target.name]: e.target.value });

    return (
        <div className="min-h-screen bg-gradient-to-br from-[#0b0b0f] to-[#1a1a20] text-white p-4 sm:p-6 lg:p-8">
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
            <header className="flex justify-between items-center mb-8">
                <h1 className="text-3xl font-bold text-white">Painel Administrativo</h1>
                <button onClick={onLogout} className="flex items-center gap-2 text-white/80 hover:text-[#ff6600] transition-colors p-2"><LogOutIcon className="w-5 h-5"/> Sair</button>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Upload Section */}
                <div className="space-y-8">
                    <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                        <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><FileTextIcon /> Upload de Aulas (CSV)</h2>
                        <input type="file" accept=".csv" onChange={handleCSVUpload} className="hidden" ref={fileInputRef}/>
                        <button onClick={() => fileInputRef.current?.click()} className="w-full bg-black/20 border-2 border-dashed border-white/30 rounded-lg p-6 text-center text-white/70 hover:border-[#ff6600] group"><UploadCloudIcon className="w-10 h-10 mx-auto mb-2 text-white/50 group-hover:text-[#ff6600]"/><span className="block text-sm">Clique ou arraste o arquivo</span></button>
                        <p className="text-xs text-white/50 mt-4 text-center">Data, Inicio, Fim, Turma, Instrutor...</p>
                    </div>

                    <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                        <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><CameraIcon /> Anúncio</h2>
                        <input type="file" accept="image/*,video/*" onChange={handleMediaUpload} className="w-full text-sm text-white/70 file:mr-4 file:py-2 file:px-4 file:rounded-full file:bg-[#ff6600] file:text-white"/>
                        {mediaPreview && <div className="mt-4 border border-white/20 rounded-lg overflow-hidden h-40 bg-black flex justify-center items-center">{mediaType === 'image' ? <img src={mediaPreview} className="h-full object-contain"/> : <video src={mediaPreview} className="h-full"/>}</div>}
                        <button onClick={handleUpdateAnuncio} className="mt-4 w-full bg-[#ff6600] text-white font-bold py-2 rounded-lg hover:bg-[#ff8533]">Atualizar Anúncio</button>
                    </div>
                </div>

                {/* Manual & List Section */}
                <div className="space-y-8">
                    <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                        <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2 mb-4"><PlusCircleIcon /> Nova Aula</h2>
                        <form onSubmit={handleAddAula} className="space-y-3">
                            <input name="data" value={newAula.data} onChange={handleInputChange} placeholder="Data" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white focus:ring-[#ff6600]" />
                            <input name="sala" value={newAula.sala} onChange={handleInputChange} placeholder="Sala" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white focus:ring-[#ff6600]" />
                            <input name="turma" value={newAula.turma} onChange={handleInputChange} placeholder="Turma" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white focus:ring-[#ff6600]" />
                            <input name="instrutor" value={newAula.instrutor} onChange={handleInputChange} placeholder="Instrutor" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white focus:ring-[#ff6600]" />
                            <input name="unidade_curricular" value={newAula.unidade_curricular} onChange={handleInputChange} placeholder="Matéria" className="w-full bg-black/20 border border-white/30 rounded-lg p-2 text-white focus:ring-[#ff6600]" />
                            <div className="flex gap-3">
                                <input name="inicio" value={newAula.inicio} onChange={handleInputChange} type="time" className="w-1/2 bg-black/20 border border-white/30 rounded-lg p-2 text-white focus:ring-[#ff6600]" />
                                <input name="fim" value={newAula.fim} onChange={handleInputChange} type="time" className="w-1/2 bg-black/20 border border-white/30 rounded-lg p-2 text-white focus:ring-[#ff6600]" />
                            </div>
                            <button type="submit" className="w-full bg-green-600 text-white font-bold py-2 rounded-lg hover:bg-green-700">Adicionar</button>
                        </form>
                    </div>
                </div>
            </div>

            {/* Lista Editável de Aulas */}
            <div className="mt-8 bg-white/10 backdrop-blur-lg border border-white/20 rounded-2xl p-6 shadow-lg">
                <div className="flex justify-between items-center mb-6">
                     <h2 className="text-xl font-bold text-[#ff6600] flex items-center gap-2"><FileTextIcon /> Aulas Cadastradas Hoje ({new Date().toLocaleDateString('pt-BR')})</h2>
                     <button onClick={context.clearAulas} className="text-red-500 text-sm hover:text-red-400 flex items-center gap-1 border border-red-500/30 px-3 py-1 rounded-full"><TrashIcon className="w-4 h-4" /> Limpar Tudo</button>
                </div>

                <div className="space-y-2 max-h-[600px] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-[#ff6600] scrollbar-track-black/20">
                    {sortedAulas.length === 0 ? (
                        <p className="text-white/50 text-center py-8">Nenhuma aula cadastrada para hoje.</p>
                    ) : (
                        sortedAulas.map((aula) => (
                            <AulaItem key={aula.id} aula={aula} onUpdate={context.updateAula} onDelete={context.deleteAula} />
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

const AdminScreen: React.FC<{ onReturnToDashboard: () => void }> = ({ onReturnToDashboard }) => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

    const handleLoginSuccess = () => { setIsAuthenticated(true); setToast({ message: 'Login realizado!', type: 'success' }); };
    const handleLoginError = (msg: string) => setToast({ message: msg, type: 'error' });

    if (isAuthenticated) return <AdminPanel onLogout={onReturnToDashboard} />;

    return (
        <div className="h-screen w-screen bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-[#1a1c2e] via-[#0f1016] to-[#000000] flex items-center justify-center">
             <button onClick={onReturnToDashboard} className="fixed top-6 left-6 text-white/50 hover:text-[#ff6600] flex items-center gap-2 z-50 transition-colors"><LogOutIcon className="w-5 h-5 rotate-180" /> <span className="text-sm font-bold uppercase">Voltar ao Painel</span></button>
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
            <LoginModal onLoginSuccess={handleLoginSuccess} onLoginError={handleLoginError} />
        </div>
    );
};

export default AdminScreen;

export interface Aula {
  id: string;
  data: string; // Formato DD/MM/YYYY
  sala: string;
  turma: string;
  instrutor: string;
  unidade_curricular: string;
  inicio: string;
  fim: string;
  turno?: string;
}

export interface Anuncio {
  id: string;
  type: 'image' | 'video';
  src: string;
}

export interface DataContextType {
  aulas: Aula[];
  anuncios: Anuncio[];
  loading: boolean;
  error: string | null;
  addAula: (aula: Omit<Aula, 'id'>) => void;
  updateAulasFromCSV: (data: Omit<Aula, 'id'>[]) => void;
  updateAula: (id: string, aula: Partial<Aula>) => Promise<void>;
  deleteAula: (id: string) => Promise<void>;
  clearAulas: () => void;
  addAnuncio: (anuncio: Omit<Anuncio, 'id'>) => void;
  deleteAnuncio: (id: string) => void;
}

import express from 'express';
import cors from 'cors';
import bodyParser from 'body-parser';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

// Configuração para __dirname em ES Modules
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = 3001;
const DB_FILE = path.join(__dirname, 'db.json');

// Aumentando limite para suportar imagens/vídeos grandes em base64
// Vídeos base64 são 33% maiores que o binário, 500mb garante uploads seguros
app.use(bodyParser.json({ limit: '500mb' }));
app.use(bodyParser.urlencoded({ limit: '500mb', extended: true }));
app.use(cors());

// Dados iniciais (Mock) caso o arquivo não exista
const INITIAL_DATA = {
  aulas: [
    { id: '1', sala: 'Lab 01 - Redes', turma: 'Téc. Redes 2023.2', instrutor: 'Carlos Silva', unidade_curricular: 'Administração de Servidores', inicio: '08:00', fim: '12:00', turno: 'Manhã', data: new Date().toLocaleDateString('pt-BR') },
    { id: '2', sala: 'Lab 02 - Programação', turma: 'Téc. ADS 2024.1', instrutor: 'Ana Pereira', unidade_curricular: 'Lógica de Programação', inicio: '08:00', fim: '12:00', turno: 'Manhã', data: new Date().toLocaleDateString('pt-BR') }
  ],
  anuncios: [] // Array de anúncios
};

// Função auxiliar para ler o banco de dados
const readDB = () => {
  if (!fs.existsSync(DB_FILE)) {
    fs.writeFileSync(DB_FILE, JSON.stringify(INITIAL_DATA, null, 2));
    return INITIAL_DATA;
  }
  try {
    const data = fs.readFileSync(DB_FILE, 'utf8');
    const parsed = JSON.parse(data);
    // Migração simples caso o db antigo tenha 'anuncio' objeto em vez de 'anuncios' array
    if (parsed.anuncio && !parsed.anuncios) {
        parsed.anuncios = [];
        delete parsed.anuncio;
    }
    return parsed;
  } catch (error) {
    console.error("Erro ao ler DB:", error);
    return INITIAL_DATA;
  }
};

// Função auxiliar para escrever no banco de dados
const writeDB = (data) => {
  fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
};

// --- ROTAS ---

// GET: Retorna todos os dados
app.get('/api/data', (req, res) => {
  const data = readDB();
  // Simular pequeno delay de rede para UI
  setTimeout(() => res.json(data), 300);
});

// POST: Adicionar uma aula
app.post('/api/aulas', (req, res) => {
  const db = readDB();
  const novaAula = { ...req.body, id: new Date().toISOString() };
  db.aulas.push(novaAula);
  writeDB(db);
  res.json(db.aulas);
});

// POST: Atualizar aulas em massa (CSV)
app.post('/api/aulas/bulk', (req, res) => {
  const db = readDB();
  const novasAulas = req.body.map(d => ({ 
    ...d, 
    id: `${d.sala}-${d.turma}-${Math.random().toString(36).substr(2, 9)}` 
  }));
  db.aulas = novasAulas;
  writeDB(db);
  res.json(db.aulas);
});

// PUT: Atualizar uma aula específica
app.put('/api/aulas/:id', (req, res) => {
  const db = readDB();
  const { id } = req.params;
  const index = db.aulas.findIndex(a => a.id === id);

  if (index !== -1) {
    db.aulas[index] = { ...db.aulas[index], ...req.body };
    writeDB(db);
    res.json(db.aulas);
  } else {
    res.status(404).json({ message: 'Aula não encontrada' });
  }
});

// DELETE: Limpar todas as aulas
app.delete('/api/aulas', (req, res) => {
  const db = readDB();
  db.aulas = [];
  writeDB(db);
  res.json(db.aulas);
});

// DELETE: Deletar aula específica (opcional, mas boa prática)
app.delete('/api/aulas/:id', (req, res) => {
  const db = readDB();
  const { id } = req.params;
  db.aulas = db.aulas.filter(a => a.id !== id);
  writeDB(db);
  res.json(db.aulas);
});

// POST: Atualizar Lista de Anúncios (Substitui ou Adiciona)
// Vamos fazer um endpoint que aceita a lista inteira ou operações. 
// Para simplificar o front, vamos ter endpoints de adicionar e remover.

app.post('/api/anuncios', (req, res) => {
  const db = readDB();
  const novoAnuncio = { ...req.body, id: Date.now().toString() };

  // Limite de 4
  if (db.anuncios && db.anuncios.length >= 4) {
      return res.status(400).json({ message: "Limite de 4 anúncios atingido." });
  }

  if (!db.anuncios) db.anuncios = [];
  db.anuncios.push(novoAnuncio);
  writeDB(db);
  res.json(db.anuncios);
});

app.delete('/api/anuncios/:id', (req, res) => {
    const db = readDB();
    const { id } = req.params;
    if (db.anuncios) {
        db.anuncios = db.anuncios.filter(a => a.id !== id);
        writeDB(db);
    }
    res.json(db.anuncios || []);
});

app.listen(PORT, () => {
  console.log(`Servidor rodando em http://localhost:${PORT}`);
  console.log(`Certifique-se de configurar VITE_API_URL=http://localhost:${PORT} no seu .env.local ou o front usará este padrão.`);
});

