import React, { createContext, useState, useEffect, ReactNode, useCallback } from 'react';
import { Aula, Anuncio, DataContextType } from '../types';

// Função para determinar a URL da API dinamicamente
const getApiUrl = () => {
  const envUrl = (import.meta as any).env?.VITE_API_URL;
  if (envUrl) return envUrl;
  const hostname = window.location.hostname;
  return `http://${hostname}:3001`;
};

const API_URL = getApiUrl();

export const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [aulas, setAulas] = useState<Aula[]>([]);
  const [anuncios, setAnunciosState] = useState<Anuncio[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Função para buscar dados do servidor
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/api/data`);
      if (!response.ok) throw new Error('Falha na comunicação com o servidor');

      const data = await response.json();
      setAulas(data.aulas || []);
      setAnunciosState(data.anuncios || []);
      setError(null);
    } catch (err) {
      console.error(err);
      setError(`Falha ao conectar em ${API_URL}. Verifique se o server.js está rodando.`);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addAula = useCallback(async (aula: Omit<Aula, 'id'>) => {
    try {
      const response = await fetch(`${API_URL}/api/aulas`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(aula),
      });
      if (!response.ok) throw new Error('Erro ao adicionar aula');
      const updatedAulas = await response.json();
      setAulas(updatedAulas);
    } catch (err) {
      console.error(err);
      alert('Erro ao salvar aula no servidor.');
    }
  }, []);

  const updateAulasFromCSV = useCallback(async (data: Omit<Aula, 'id'>[]) => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/api/aulas/bulk`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error('Erro ao importar CSV');
      const updatedAulas = await response.json();
      setAulas(updatedAulas);
    } catch (err) {
      console.error(err);
      alert('Erro ao processar CSV no servidor.');
    } finally {
      setLoading(false);
    }
  }, []);

  const updateAula = useCallback(async (id: string, aulaData: Partial<Aula>) => {
      try {
          const response = await fetch(`${API_URL}/api/aulas/${id}`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(aulaData),
          });
          if (!response.ok) throw new Error('Erro ao atualizar aula');
          const updatedAulas = await response.json();
          setAulas(updatedAulas);
      } catch (err) {
          console.error(err);
          alert('Erro ao atualizar aula.');
      }
  }, []);

  const deleteAula = useCallback(async (id: string) => {
    try {
        const response = await fetch(`${API_URL}/api/aulas/${id}`, {
            method: 'DELETE',
        });
        if (!response.ok) throw new Error('Erro ao deletar aula');
        const updatedAulas = await response.json();
        setAulas(updatedAulas);
    } catch (err) {
        console.error(err);
        alert('Erro ao deletar aula.');
    }
  }, []);

  const clearAulas = useCallback(async () => {
    try {
      if(!confirm("Tem certeza que deseja apagar todas as aulas do servidor?")) return;
      const response = await fetch(`${API_URL}/api/aulas`, {
        method: 'DELETE',
      });
      if (!response.ok) throw new Error('Erro ao limpar aulas');
      setAulas([]);
    } catch (err) {
      console.error(err);
      alert('Erro ao limpar dados.');
    }
  }, []);

  const addAnuncio = useCallback(async (novoAnuncio: Omit<Anuncio, 'id'>) => {
    try {
      const response = await fetch(`${API_URL}/api/anuncios`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(novoAnuncio),
      });
      if (!response.ok) {
          const errData = await response.json();
          throw new Error(errData.message || 'Erro ao adicionar anúncio');
      }
      const updatedAnuncios = await response.json();
      setAnunciosState(updatedAnuncios);
    } catch (err) {
      console.error(err);
      alert(err instanceof Error ? err.message : 'Erro ao salvar anúncio.');
    }
  }, []);

  const deleteAnuncio = useCallback(async (id: string) => {
      try {
          const response = await fetch(`${API_URL}/api/anuncios/${id}`, {
              method: 'DELETE',
          });
          if(!response.ok) throw new Error("Erro ao deletar anúncio");
          const updatedAnuncios = await response.json();
          setAnunciosState(updatedAnuncios);
      } catch (err) {
          console.error(err);
          alert("Erro ao remover anúncio.");
      }
  }, []);

  return (
    <DataContext.Provider value={{ aulas, anuncios, loading, error, addAula, updateAulasFromCSV, updateAula, deleteAula, clearAulas, addAnuncio, deleteAnuncio }}>
      {children}
    </DataContext.Provider>
  );
};

import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';

interface ThemeContextType {
  isDarkMode: boolean;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isDarkMode, setIsDarkMode] = useState(true);

  const toggleTheme = () => {
    setIsDarkMode(prev => !prev);
  };

  return (
    <ThemeContext.Provider value={{ isDarkMode, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

import React, { useState } from 'react';
import DashboardScreen from './components/DashboardScreen';
import AdminScreen from './components/AdminScreen';
import { DataProvider } from './context/DataContext';
import { ThemeProvider } from './context/ThemeContext';

function App() {
  const [view, setView] = useState<'dashboard' | 'admin'>('dashboard');

  const showAdmin = () => setView('admin');
  const showDashboard = () => setView('dashboard');

  return (
    <ThemeProvider>
      <DataProvider>
        <div className="w-full h-full">
          {view === 'dashboard' ? (
            <DashboardScreen onAdminClick={showAdmin} />
          ) : (
            <AdminScreen onReturnToDashboard={showDashboard} />
          )}
        </div>
      </DataProvider>
    </ThemeProvider>
  );
}

export default App;

