// Announcement Panel (Carousel)
const AnnouncementPanel: React.FC<{ anuncios: Anuncio[] }> = ({ anuncios }) => {
    const [currentIndex, setCurrentIndex] = useState(0);
    const { isDarkMode } = useTheme();

    useEffect(() => {
        if (anuncios.length <= 1) return;

        const interval = setInterval(() => {
            setCurrentIndex((prev) => (prev + 1) % anuncios.length);
        }, 10000); // 10 segundos

        return () => clearInterval(interval);
    }, [anuncios.length]);

    if (anuncios.length === 0) return null;

    const currentAnuncio = anuncios[currentIndex];

    return (
        <div className={`w-full h-full p-4 flex items-center justify-center transition-colors duration-500`}>
            {/* Container com borda e arredondado, não colado nas bordas */}
            <div className={`relative w-full h-full overflow-hidden rounded-2xl shadow-2xl border ${isDarkMode ? 'border-white/10 bg-black/40' : 'border-slate-200 bg-white/50'}`}>

                {/* Indicadores de Carrossel */}
                {anuncios.length > 1 && (
                    <div className="absolute bottom-4 left-0 right-0 z-30 flex justify-center gap-2">
                        {anuncios.map((_, idx) => (
                            <div 
                                key={idx}
                                className={`h-1.5 rounded-full transition-all duration-300 ${idx === currentIndex ? 'w-6 bg-[#ff6600]' : 'w-1.5 bg-white/50'}`}
                            />
                        ))}
                    </div>
                )}

                {/* Conteúdo */}
                {currentAnuncio.type === 'image' && (
                    <img 
                        key={currentAnuncio.id}
                        src={currentAnuncio.src} 
                        alt="Anúncio" 
                        className="w-full h-full object-fill animate-fadeIn" 
                    />
                )}
