            </main>

            <div className="fixed bottom-4 left-4 flex gap-3 z-50">
                <button
                    onClick={onAdminClick}
                    className={`p-3 rounded-full transition-all duration-300 group backdrop-blur-md border ${
                        isDarkMode 
                        ? 'text-white/20 hover:text-[#ff6600] hover:bg-white/10 border-transparent hover:border-white/10' 
