        </div>
    );
};

const DashboardScreen: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const context = useContext(DataContext);
    const { isDarkMode, toggleTheme } = useTheme();
    const [filteredAulas, setFilteredAulas] = useState<Aula[]>([]);
    const [visibleAulas, setVisibleAulas] = useState<Aula[]>([]);
    const [currentShift, setCurrentShift] = useState<string>('Matutino');
    const [page, setPage] = useState(0);
    const [isFullscreen, setIsFullscreen] = useState(false);

    const containerRef = useRef<HTMLDivElement>(null);

    // Listener para mudança de estado de tela cheia
    useEffect(() => {
        const handleFullscreenChange = () => {
            setIsFullscreen(!!document.fullscreenElement);
        };
        document.addEventListener('fullscreenchange', handleFullscreenChange);
        return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
    }, []);

    const toggleFullScreen = () => {
        if (!document.fullscreenElement) {
            document.documentElement.requestFullscreen().catch(err => {
                console.log(`Erro ao ativar tela cheia: ${err.message}`);
            });
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
        }
    };

    useEffect(() => {
        const updateShift = () => {
            const now = new Date();
            const totalMinutes = now.getHours() * 60 + now.getMinutes();

            // Lógica de tempo atualizada para os novos nomes
            if (totalMinutes < 720) { 
                setCurrentShift('Matutino');
            } else if (totalMinutes < 1080) {
                setCurrentShift('Vespertino');
            } else {
                setCurrentShift('Noturno');
            }
        };
        updateShift();
        const interval = setInterval(updateShift, 60000);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (context && !context.loading) {
            const today = new Date().toLocaleDateString('pt-BR');
            const filtered = context.aulas.filter(aula => {
                const aulaData = aula.data || '';

                // Normaliza para comparação (ex: 'Manhã' == 'Matutino')
                const turnoAulaNorm = normalizeTurno(aula.turno);
                const turnoAtualNorm = normalizeTurno(currentShift);

                return aulaData === today && turnoAulaNorm === turnoAtualNorm;
            });
            setFilteredAulas(filtered);
            setPage(0);
        }
    }, [context, currentShift]);

    const { anuncios } = context || {};
    const hasAnuncio = anuncios && anuncios.length > 0;
    const ITEMS_PER_PAGE = hasAnuncio ? 8 : 12;

    useEffect(() => {
        const totalPages = Math.ceil(filteredAulas.length / ITEMS_PER_PAGE);
        const start = page * ITEMS_PER_PAGE;
        const end = start + ITEMS_PER_PAGE;
        setVisibleAulas(filteredAulas.slice(start, end));

        if (totalPages > 1) {
            const interval = setInterval(() => {
                setPage(prevPage => (prevPage + 1) % totalPages);
            }, 15000);
            return () => clearInterval(interval);
        }
    }, [filteredAulas, page, ITEMS_PER_PAGE]);

    if (!context) {
        return <div className="text-red-500 p-10">Erro: Contexto não encontrado.</div>;
    }

    const { loading, error } = context;

