            isDarkMode 
            ? 'bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-[#1a1c2e] via-[#0f1016] to-[#000000] text-white' 
            : 'bg-gray-100 text-slate-800'
        }`}>

            <Header currentShift={currentShift} onFullscreen={toggleFullScreen} />

            <main className="flex-1 overflow-hidden p-6 relative flex flex-col">

                <div className={`flex-1 w-full flex backdrop-blur-xl border rounded-3xl shadow-2xl overflow-hidden relative transition-colors duration-500 ${
                    isDarkMode ? 'bg-white/5 border-white/10' : 'bg-white/40 border-slate-200'
                }`}>

                    {/* Lista de Aulas */}
                    <div className={`flex flex-col h-full relative ${hasAnuncio ? 'w-[60%] border-r' : 'w-full'} ${isDarkMode ? 'border-white/10' : 'border-slate-200'}`}>

                        <div className="flex-1 p-6 overflow-hidden flex flex-col justify-center">

                            {error && (
                                <div className="bg-red-500/20 border border-red-500/50 text-red-200 p-6 rounded-xl text-center mb-8 animate-pulse shadow-lg shadow-red-900/20">
                                    {error}
                                </div>
