const DashboardScreen: React.FC<{ onAdminClick: () => void }> = ({ onAdminClick }) => {
    const context = useContext(DataContext);
    const { isDarkMode, toggleTheme } = useTheme();
    const [filteredAulas, setFilteredAulas] = useState<Aula[]>([]);
    const [visibleAulas, setVisibleAulas] = useState<Aula[]>([]);
    const [currentShift, setCurrentShift] = useState<string>('Matutino');
    const [page, setPage] = useState(0);
    const [isFullscreen, setIsFullscreen] = useState(false);

    useEffect(() => {
        const handleFS = () => setIsFullscreen(!!document.fullscreenElement);
        document.addEventListener('fullscreenchange', handleFS);
        return () => document.removeEventListener('fullscreenchange', handleFS);
    }, []);

    useEffect(() => {
        const update = () => {
            const now = new Date();
            const h = now.getHours();
            const m = now.getMinutes();
            const totalMin = (h * 60) + m;

            if (totalMin >= 360 && totalMin <= 690) setCurrentShift('Matutino');
            else if (totalMin >= 691 && totalMin <= 1050) setCurrentShift('Vespertino');
            else if (totalMin >= 1051 && totalMin <= 1320) setCurrentShift('Noturno');
            else {
                if (h < 6) setCurrentShift('Matutino');
                else setCurrentShift('Noturno');
            }
        };
        update();
        const interval = setInterval(update, 60000);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (context && !context.loading) {
            const now = new Date();
            const day = String(now.getDate()).padStart(2, '0');
            const month = String(now.getMonth() + 1).padStart(2, '0');
            const year = now.getFullYear();
            const todayStr = `${day}/${month}/${year}`;

            const filtered = context.aulas.filter(a => {
                const aulaData = a.data.trim();
                return aulaData === todayStr && normalizeTurno(a.turno) === normalizeTurno(currentShift);
            });

            setFilteredAulas(filtered);
            setPage(0);
        }
    }, [context?.aulas, context?.loading, currentShift]);

    const [itemsPerPage, setItemsPerPage] = useState(8);
    useEffect(() => {
        const updateItems = () => {
            const hasAds = (context?.anuncios?.length || 0) > 0;
            if (window.innerWidth < 768) setItemsPerPage(4);
            else if (hasAds) setItemsPerPage(6);
            else setItemsPerPage(8);
        };
        updateItems();
        window.addEventListener('resize', updateItems);
        return () => window.removeEventListener('resize', updateItems);
    }, [context?.anuncios]);

    useEffect(() => {
        const total = Math.ceil(filteredAulas.length / itemsPerPage);
        setVisibleAulas(filteredAulas.slice(page * itemsPerPage, (page + 1) * itemsPerPage));
        if (total > 1) {
            const timer = setInterval(() => setPage(p => (p + 1) % total), 15000);
            return () => clearInterval(timer);
        }
    }, [filteredAulas, page, itemsPerPage]);

    if (!context) return null;

    const hasAnuncios = (context.anuncios?.length || 0) > 0;

    return (
        <div className={`min-h-screen w-screen overflow-x-hidden flex flex-col transition-colors duration-1000 ${isDarkMode ? 'bg-[#0a0a0f] text-white' : 'bg-slate-50 text-slate-800'}`}>
            <Header currentShift={currentShift} onFullscreen={() => document.documentElement.requestFullscreen()} />

            <main className="flex-1 p-4 md:p-8 flex flex-col lg:flex-row gap-8">
                <div className={`flex-1 flex flex-col transition-all duration-500 ${hasAnuncios ? 'lg:w-2/3' : 'w-full'}`}>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-4 md:gap-8 auto-rows-min">
                        {visibleAulas.map((a, idx) => <ClassCard key={a.id} aula={a} index={idx} />)}
                    </div>
                    {filteredAulas.length === 0 && (
                        <div className="flex-1 flex items-center justify-center opacity-10 flex-col gap-6 text-center py-20">
                            <div className="p-8 md:p-12 rounded-full border-2 md:border-4 border-dashed border-white/20"><ClockIcon className="w-16 h-16 md:w-24 md:h-24 stroke-[1px]" /></div>
                            <div>
                                <p className="text-xl md:text-2xl font-black uppercase tracking-[0.2em] md:tracking-[0.4em]">Sem atividades agora</p>
                                <p className="text-[9px] md:text-[10px] mt-2 opacity-50 tracking-widest font-bold uppercase">Aguardando novos dados no CSV</p>
                            </div>
                        </div>
                    )}
                    {filteredAulas.length > itemsPerPage && (
                        <div className="mt-8 flex justify-center gap-3 pb-4">
                            {Array.from({ length: Math.ceil(filteredAulas.length / itemsPerPage) }).map((_, i) => (
                                <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${i === page ? 'w-10 md:w-12 bg-[#ff6600]' : 'w-2 bg-white/10'}`} />
                            ))}
                        </div>
                    )}
                </div>

                {hasAnuncios && (
                    <aside className="hidden lg:block w-1/3 h-[calc(100vh-160px)] rounded-[3rem] overflow-hidden border border-white/5 shadow-2xl bg-black/40 relative">
                         {context.anuncios.map((ad, idx) => {
                             const isVisible = idx === (Math.floor(Date.now()/10000) % context.anuncios.length);
                             return (
                                <div key={ad.id} className={`absolute inset-0 w-full h-full transition-opacity duration-1000 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
                                    {ad.type === 'image' ? <img src={ad.src} className="w-full h-full object-cover" /> : <video src={ad.src} autoPlay loop muted className="w-full h-full object-cover" />}
                                </div>
                             );
                         })}
                    </aside>
                )}
            </main>

            {!isFullscreen && (
                <div className="fixed bottom-6 right-6 flex gap-3 z-50">
                    <button onClick={toggleTheme} className="p-4 md:p-5 rounded-2xl md:rounded-3xl bg-white/5 backdrop-blur-2xl border border-white/10 text-white hover:bg-[#ff6600] transition-all shadow-2xl">
                        {isDarkMode ? <SunIcon className="w-5 h-5 md:w-6 md:h-6" /> : <MoonIcon className="w-5 h-5 md:w-6 md:h-6" />}
                    </button>
                    <button onClick={onAdminClick} className="hidden md:flex p-5 rounded-3xl bg-white/5 backdrop-blur-2xl border border-white/10 text-white hover:bg-[#ff6600] transition-all shadow-2xl group">
                        <SettingsIcon className="w-6 h-6 group-hover:rotate-180 transition-transform duration-700" />
                    </button>
                </div>
            )}
        </div>
    );
};
export default DashboardScreen;

import React, { useState, useContext, useMemo, useRef } from 'react';
import { DataContext } from '../context/DataContext';
import { Aula } from '../types';
import { XIcon, UploadCloudIcon, FileTextIcon, TrashIcon, LogOutIcon, CameraIcon, SettingsIcon } from './Icons';

// Definindo tipos globais para as libs carregadas via CDN
declare const XLSX: any;
declare const pdfjsLib: any;

const calcularTurnoPorHorario = (horarioStr: string): string => {
    if (!horarioStr || !horarioStr.includes(':')) return 'Matutino';
    const [horas, minutos] = horarioStr.split(':').map(Number);
    const totalMinutos = (horas * 60) + (minutos || 0);
    if (totalMinutos >= 360 && totalMinutos <= 690) return 'Matutino';
    if (totalMinutos >= 691 && totalMinutos <= 1050) return 'Vespertino';
    if (totalMinutos >= 1051 && totalMinutos <= 1320) return 'Noturno';
    return totalMinutos < 360 ? 'Matutino' : 'Noturno';
};

const AdminPanel: React.FC<{ onLogout: () => void }> = ({ onLogout }) => {
    const context = useContext(DataContext);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [loadingSync, setLoadingSync] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const aulasExibidas = useMemo(() => {
        let items = context ? [...context.aulas] : [];
        if (startDate || endDate) {
            items = items.filter(a => {
                const parts = a.data.split('/');
                if (parts.length !== 3) return true;
                const [d, m, y] = parts;
                const date = new Date(`${y}-${m}-${d}`);
                if (startDate && date < new Date(startDate)) return false;
                if (endDate && date > new Date(endDate)) return false;
                return true;
            });
        }
        return items.sort((a, b) => {
            const dateA = a.data.split('/').reverse().join('-');
            const dateB = b.data.split('/').reverse().join('-');
            return dateA.localeCompare(dateB) || a.inicio.localeCompare(b.inicio);
        });
    }, [context?.aulas, startDate, endDate]);

    const processExcelOrCSV = (data: any) => {
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

        if (jsonData.length < 2) return [];

        const headers = (jsonData[0] as string[]).map(h => String(h).toLowerCase().trim());
        const idx = {
            data: headers.findIndex(h => h.includes('data')),
            sala: headers.findIndex(h => h.includes('ambiente') || h.includes('sala') || h.includes('justificativa')),
            turma: headers.findIndex(h => h.includes('turma') || h.includes('tipo')),
            instrutor: headers.findIndex(h => h.includes('instrutor') || h.includes('reserva')),
            uc: headers.findIndex(h => h.includes('unidade') || h.includes('curricular') || h.includes('solicitante')),
            inicio: headers.findIndex(h => h.includes('inicio') || h.includes('início')),
            fim: headers.findIndex(h => h.includes('fim'))
        };

        const rows = jsonData.slice(1);
        return rows.map((v: any) => {
            const h = v[idx.inicio] || '';
            return {
                data: v[idx.data] || '',
                sala: String(v[idx.sala] || '').replace(/^["']|["']$/g, ''),
                turma: v[idx.turma] || '',
                instrutor: v[idx.instrutor] || '',
                unidade_curricular: v[idx.uc] || '',
                inicio: h,
                fim: v[idx.fim] || '',
                turno: calcularTurnoPorHorario(h)
            };
        }).filter(a => a.data && a.inicio);
    };

    const processPDF = async (arrayBuffer: ArrayBuffer) => {
        pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/pdf.worker.min.js';
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        let fullText = "";

        for (let i = 1; i <= pdf.numPages; i++) {
            const page = await pdf.getPage(i);
            const content = await page.getTextContent();
            const strings = content.items.map((item: any) => item.str);
            fullText += strings.join(" ") + "\n";
        }

        // Regex simples para capturar linhas que parecem com o padrão de aula do SENAI
        // Exemplo esperado: DD/MM/YYYY seguido de outros dados
        const dateRegex = /(\d{2}\/\d{2}\/\d{4})/g;
        const lines = fullText.split('\n');

        alert("O processamento de PDF é experimental e depende da estrutura do arquivo. Recomenda-se Excel ou CSV.");

        // Retornamos vazio por enquanto para não corromper, mas a estrutura está pronta
        return [];
    };

    const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        setLoadingSync(true);
        try {
            const arrayBuffer = await file.arrayBuffer();
            let processedData: Omit<Aula, 'id'>[] = [];

            if (file.name.endsWith('.pdf')) {
                processedData = await processPDF(arrayBuffer);
            } else {
                // XLSX, XLS ou CSV
                processedData = processExcelOrCSV(new Uint8Array(arrayBuffer));
            }

            if (processedData.length > 0) {
                context?.updateAulasFromCSV(processedData);
                alert(`${processedData.length} aulas importadas com sucesso!`);
            } else {
                alert("Nenhum dado válido encontrado no arquivo. Verifique os cabeçalhos.");
            }
        } catch (e: any) {
            console.error(e);
            alert(`Erro ao processar arquivo: ${e.message}`);
        } finally {
            setLoadingSync(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    if (!context) return null;

    return (
        <div className="min-h-screen bg-[#050508] text-white p-4 md:p-10 font-sans">
            <header className="flex flex-col md:flex-row justify-between items-center mb-8 md:mb-12 gap-6">
                <div className="flex flex-col items-center md:items-start">
                    <h1 className="text-3xl md:text-4xl font-black uppercase tracking-tighter">ADMINISTRAÇÃO</h1>
                    <div className="flex items-center gap-2 mt-1">
                        <span className="text-[10px] font-bold text-[#ff6600] tracking-[0.4em] uppercase opacity-60">Gestão de Arquivos</span>
                    </div>
                </div>
                <div className="flex gap-4 w-full md:w-auto">
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileUpload} 
                        accept=".csv, .xlsx, .xls, .pdf" 
                        className="hidden" 
                    />
                    <button 
                        onClick={() => fileInputRef.current?.click()} 
                        disabled={loadingSync} 
                        className="flex-1 md:flex-none bg-[#ff6600] text-white px-6 md:px-8 py-3 rounded-2xl font-black uppercase text-[10px] md:text-xs flex items-center justify-center gap-3 hover:bg-white hover:text-black transition-all shadow-2xl active:scale-95"
                    >
                        <UploadCloudIcon className="w-4 h-4 md:w-5 md:h-5" /> 
                        {loadingSync ? "Processando..." : "Importar (XLSX/PDF/CSV)"}
                    </button>
                    <button onClick={onLogout} className="p-3 bg-white/5 rounded-2xl opacity-40 hover:opacity-100 transition-opacity">
                        <LogOutIcon />
                    </button>
                </div>
            </header>

            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 md:gap-8 mb-8 md:mb-12">
                <div className="bg-white/5 p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] border border-white/5 shadow-2xl flex flex-col gap-6">
                    <div className="flex items-center gap-3"><CameraIcon className="w-6 h-6 text-[#ff6600]"/><h2 className="text-sm font-black uppercase tracking-widest">Anúncios</h2></div>
                    <div className="space-y-4">
                        <div className="flex gap-2">
                            <input id="ad-url" placeholder="URL do Vídeo/Imagem" className="flex-1 bg-black/40 border border-white/10 p-4 rounded-2xl text-[11px] outline-none" />
                            <button onClick={() => {
                                const val = (document.getElementById('ad-url') as HTMLInputElement).value;
                                if(val) { context.addAnuncio({ src: val, type: val.toLowerCase().endsWith('.mp4') ? 'video' : 'image' }); (document.getElementById('ad-url') as HTMLInputElement).value = ''; }
                            }} className="bg-white text-black px-5 rounded-2xl font-black">+</button>
                        </div>
                        <div className="grid grid-cols-4 gap-2">
                            {context.anuncios.map(ad => (
                                <div key={ad.id} className="relative group aspect-square rounded-xl overflow-hidden border border-white/10 bg-black">
                                    {ad.type === 'image' ? <img src={ad.src} className="w-full h-full object-cover opacity-50" /> : <div className="w-full h-full flex items-center justify-center text-[8px] font-bold">MOV</div>}
