);

const sanitizeDriveUrl = (url: string) => {
    if (url.includes('drive.google.com')) {
        const id = url.match(/\/d\/(.+?)\//)?.[1] || url.match(/id=(.+?)(&|$)/)?.[1];
        if (id) {
            // Links do drive para embedding direto
            return `https://drive.google.com/uc?id=${id}`;
        }
    }
    return url;
};

