                </div>
                <form onSubmit={e => { e.preventDefault(); onSave(formData); }} className="grid grid-cols-1 md:grid-cols-2 gap-5">
                    {[
                        { label: 'Turma', key: 'turma' },
                        { label: 'Ambiente / Sala', key: 'sala' },
