        return () => document.removeEventListener('fullscreenchange', handleFS);
    }, []);

    useEffect(() => {
        const detectShift = () => {
            const h = new Date().getHours();
            if (h >= 6 && h < 12) return 'Matutino';
            if (h >= 12 && h < 18) return 'Vespertino';
            return 'Noturno';
        };
        setCurrentShift(detectShift());
    }, []);

    useEffect(() => {
        if (context && !context.loading) {
            const now = new Date();
